            ["trait.damage_control.info"] = ("Clears burning, slows, stuns and shred and blocks them for 2 s (every {seconds} s).", "Xóa cháy, chậm, choáng và xé giáp, rồi miễn nhiễm 2 giây (mỗi {seconds} giây)."),
            ["trait.thermal_imager"] = ("Thermal Imager", "Kính ảnh nhiệt"),
            ["trait.thermal_imager.info"] = ("Sees through smoke out to {percent}% of its vision.", "Nhìn xuyên khói tới {percent}% tầm nhìn."),
            ["trait.laser_designator"] = ("Laser Designator", "Chỉ thị la-de"),
            ["trait.laser_designator.info"] = ("Marks what it hits for {seconds} s: allies deal {percent}% more to it and artillery reaches it from further.", "Đánh dấu mục tiêu trúng đạn {seconds} giây: đồng minh gây thêm {percent}% và pháo binh bắn tới xa hơn."),
            ["trait.ghillie_mode"] = ("Ghillie Mode", "Chế độ ngụy trang"),
            ["trait.ghillie_mode.info"] = ("After {seconds} s still and silent: hidden beyond 8 m; the first shot from hiding deals {percent}% more.", "Đứng yên và im lặng {seconds} giây: ẩn mình ngoài 8 m; phát đầu từ chỗ nấp gây thêm {percent}%."),
            ["trait.counter_battery_radar"] = ("Counter-Battery Radar", "Radar phản pháo"),
            ["trait.counter_battery_radar.info"] = ("Enemy artillery firing within {metres} m is revealed for {seconds} s, and artillery deals {percent}% more to it.", "Pháo địch khai hỏa trong {metres} m bị lộ {seconds} giây, và pháo binh gây thêm {percent}% lên nó."),
            ["trait.ew_jammer"] = ("EW Jammer", "Gây nhiễu điện tử"),
            ["trait.ew_jammer.info"] = ("Every {seconds2} s, guided rounds aimed at allies within {metres} m miss for {seconds} s.", "Mỗi {seconds2} giây, đạn dẫn đường nhắm vào đồng minh trong {metres} m bị trượt trong {seconds} giây."),
            ["trait.fire_control_computer"] = ("Fire-Control Computer", "Máy tính điều khiển hỏa lực"),
            ["trait.fire_control_computer.info"] = ("Unguided rounds lead moving targets, with {percent}% less spread against them.", "Đạn không dẫn đường đón đầu mục tiêu đang chạy, giảm {percent}% tản mát với chúng."),
            ["trait.mine_sweep"] = ("Mine Sweep", "Quét mìn"),
            ["trait.mine_sweep.info"] = ("The first mine every 30 s goes off harmlessly.", "Quả mìn đầu tiên mỗi 30 giây nổ vô hại."),
            ["trait.set_bulwark"] = ("Bulwark", "Thành lũy"),
            ["trait.set_bulwark.info"] = ("After 2 s standing still: -{percent}% damage taken, and enemies nearby shoot at it first.", "Đứng yên 2 giây: -{percent}% sát thương nhận, và địch gần đó ưu tiên bắn nó."),
            ["trait.set_hit_and_run"] = ("Hit and Run", "Đánh và chạy"),
            ["trait.set_hit_and_run.info"] = ("+{percent}% speed for 2 s after each shot; unguided rounds at it on the move get +{percent2}% spread.", "+{percent}% tốc độ trong 2 giây sau mỗi phát bắn; đạn không dẫn đường bắn vào nó khi đang chạy +{percent2}% tản mát."),
            ["trait.set_firestorm"] = ("Firestorm", "Bão lửa"),
            ["trait.set_firestorm.info"] = ("Burning enemies take {percent}% more damage, and a burning enemy's fire jumps up to {metres} m when it dies.", "Địch đang cháy nhận thêm {percent}% sát thương, và khi chết lửa lan sang kẻ địch trong {metres} m."),
            ["trait.set_deep_strike"] = ("Deep Strike", "Đòn tầm xa"),
            ["trait.set_deep_strike.info"] = ("+{percent}% damage to targets beyond 70% of its range.", "+{percent}% sát thương lên mục tiêu xa hơn 70% tầm bắn."),
            ["trait.set_shared_shield"] = ("Shared Shield", "Khiên chia sẻ"),
            ["trait.set_shared_shield.info"] = ("Every {seconds} s, a {percent}% barrier for the weakest ally within {metres} m.", "Mỗi {seconds} giây, khiên {percent}% cho đồng minh yếu nhất trong {metres} m."),
            ["trait.set_strafing_run"] = ("Strafing Run", "Càn quét"),
            ["trait.set_strafing_run.info"] = ("Every {count}th salvo fires twice; flares every {seconds} s.", "Mỗi loạt thứ {count} bắn hai lần; thả mồi nhiệt mỗi {seconds} giây."),
            ["trait.set_swarm"] = ("Swarm", "Bầy đàn"),
            ["trait.set_swarm.info"] = ("Each kill launches a kamikaze drone at the nearest enemy (at most one every {seconds} s).", "Mỗi lần hạ địch phóng một drone cảm tử vào kẻ địch gần nhất (tối đa một chiếc mỗi {seconds} giây)."),
            ["trait.set_salvage_rights"] = ("Salvage Rights", "Quyền thu hồi"),
            ["trait.set_salvage_rights.info"] = ("Kills refund {percent}% more CP, and {percent2}% of its cost comes back when it falls.", "Hạ địch hoàn thêm {percent}% CP, và hoàn lại {percent2}% giá khi nó bị hạ."),
            ["trait.set_ghost_net"] = ("Ghost Net", "Lưới bóng ma"),
            ["trait.set_ghost_net.info"] = ("+{percent}% damage in smoke or hidden; the first missile at it each life loses lock.", "+{percent}% sát thương khi trong khói hoặc đang ẩn; tên lửa đầu tiên nhắm vào nó mỗi mạng bị mất khóa."),
            ["trait.set_heavy_round"] = ("Heavy Round", "Đạn hạng nặng"),
            ["trait.set_heavy_round.info"] = ("Every {count}th shot deals +{percent}% and bursts over 4 m (every 3rd with Overpressure Chamber).", "Mỗi phát thứ {count} gây thêm {percent}% và nổ lan 4 m (mỗi phát thứ 3 nếu có Buồng quá áp)."),
            ["trait.set_pack_hunt"] = ("Pack Hunt", "Săn theo bầy"),
            ["trait.set_pack_hunt.info"] = ("+{percent}% damage for each ally within {metres} m, up to {count}.", "+{percent}% sát thương cho mỗi đồng minh trong {metres} m, tối đa {count}."),
            ["trait.set_pack_focus"] = ("Focus Fire", "Dồn hỏa lực"),
            ["trait.set_pack_focus.info"] = ("When 3 or more of your vehicles fire at one target: +{percent}% fire rate.", "Khi từ 3 xe ta trở lên cùng bắn một mục tiêu: +{percent}% tốc độ bắn."),
            ["trait.set_phoenix"] = ("Rebirth Shield", "Khiên tái sinh"),
            ["trait.set_phoenix.info"] = ("Repairs past full health become a shield, up to {percent}% of its health, for {seconds} s.", "Lượng hồi máu vượt quá máu tối đa thành khiên, tối đa {percent}% máu, tồn tại {seconds} giây."),
            ["trait.set_bulwark_post"] = ("Field Gun Post", "Ụ súng dã chiến"),
            ["trait.set_bulwark_post.info"] = ("A tower that falls leaves a machine-gun post for {seconds} s.", "Tháp bị phá để lại một ụ súng máy tạm trong {seconds} giây."),
