            ["unit.lancet_truck"] = ("Loitering munition truck", "Xe phóng đạn lảng vảng"),
            ["short.shahed_truck"] = ("Kamikaze drones", "Drone cảm tử"),
            ["unit.shahed_truck"] = ("Long-range drone launcher", "Xe phóng drone cảm tử tầm xa"),
            ["short.iron_beam"] = ("Laser AA", "La-de PK"),
            ["unit.iron_beam"] = ("Laser AA", "Xe la-de phòng không"),
            ["short.railgun_truck"] = ("Railgun", "Pháo điện từ"),
            ["unit.railgun_truck"] = ("Railgun truck", "Xe pháo điện từ"),
            ["short.turtle_tank"] = ("Turtle tank", "Tăng rùa"),
            ["unit.turtle_tank"] = ("Turtle tank", "Tăng mái che"),
            ["short.bmpt"] = ("Tank support", "Hỗ trợ tăng"),
            ["unit.bmpt"] = ("Tank support vehicle", "Xe hỗ trợ tăng"),
            ["short.sapper"] = ("Sapper", "Công binh CT"),
            ["unit.sapper"] = ("Fortification sapper", "Xe công binh công trình"),
            ["note.scout_jeep"] = ("Fast and cheap, with a long sight: it finds the enemy and takes points early. It cannot stand up to a fight.", "Nhanh, rẻ, nhìn xa: đi trinh sát và chiếm cứ điểm sớm. Không chịu nổi giao tranh."),
            ["note.armored_car"] = ("A 25 mm autocannon on eight wheels: fast, good against light vehicles and helicopters, weak against tanks.", "Pháo 25 mm trên xe tám bánh: nhanh, mạnh với xe nhẹ và trực thăng, yếu trước xe tăng."),
            ["note.rocket_technical"] = ("A pickup with a rocket pod: a cheap salvo from a distance, then a long reload. Paper armour.", "Bán tải gắn giàn rốc-két: một loạt rẻ từ xa rồi nạp lâu. Giáp mỏng như giấy."),
            ["note.apc"] = ("A BTR-82A: 30 mm cannon and a machine gun, captures points fast, pops smoke when shot at.", "BTR-82A: pháo 30 mm và súng máy, chiếm cứ điểm nhanh, thả khói khi bị bắn."),
            ["note.light_tank"] = ("A light tank: quick, cheap, a real gun. It loses to anything heavier head on.", "Tăng nhẹ: nhanh, rẻ, có pháo thật. Thua mọi thứ nặng hơn khi đối đầu trực diện."),
            ["note.main_battle_tank"] = ("The backbone: a 120 mm gun, thick front armour, a coaxial and a roof machine gun.", "Xương sống của quân đội: pháo 120 mm, giáp trước dày, súng máy đồng trục và trên nóc."),
            ["note.heavy_tank"] = ("The breakthrough tank: its 152 mm loads armour-piercing for armour and high explosive for structures and light vehicles on its own; a 30 mm autocannon beside it answers helicopters. Front armour 4, sides 3. Slow.", "Xe đột phá: pháo 152 mm tự đổi đạn xuyên cho xe có giáp và đạn nổ mạnh cho công trình, xe nhẹ; pháo 30 mm bên cạnh đánh trực thăng. Giáp trước cấp 4, hông cấp 3. Chậm."),
            ["note.tank_destroyer"] = ("A 125 mm gun, as on the 2S25 Sprut, that outranges tanks. Its armour is thin: keep it behind the line.", "Pháo 125 mm như pháo tự hành 2S25, bắn xa hơn xe tăng. Giáp mỏng: giữ phía sau tuyến đầu."),
            ["note.flame_tank"] = ("Burns anything close, deadly to light vehicles and bunkers; it must get very near.", "Thiêu mọi thứ ở gần, rất mạnh với xe nhẹ và lô cốt; phải áp sát mới bắn được."),
            ["note.mortar_carrier"] = ("A 120 mm mortar that lobs shells over cover. It needs someone to see the target.", "Súng cối 120 mm bắn cầu vồng qua vật cản. Cần đồng đội nhìn thấy mục tiêu."),
            ["note.artillery"] = ("A truck-mounted 155 mm gun: long range, stops to fire, moves 15-20 m after every three rounds (shoot and scoot), and hits a marked target almost dead on.", "Pháo 155 mm trên xe tải: tầm xa, dừng lại để bắn, cứ ba phát lại dời 15–20 m (bắn rồi dời), bắn mục tiêu bị đánh dấu gần như không tản mát."),
            ["note.mlrs"] = ("GMLRS: six guided rockets that land where they are aimed, from farther than any tube gun.", "GMLRS: sáu rốc-két dẫn đường rơi đúng điểm ngắm, xa hơn mọi khẩu pháo nòng."),
            ["note.aa_vehicle"] = ("Twin 35 mm guns and a short-range missile: shreds helicopters and drones.", "Pháo đôi 35 mm và tên lửa tầm ngắn: xé nát trực thăng và drone."),
            ["note.sam_launcher"] = ("Long-range anti-aircraft missiles fired in pairs; it must stop to fire and cannot fight tanks.", "Tên lửa phòng không tầm xa bắn theo cặp; phải dừng để bắn và không đánh được xe tăng."),
            ["note.scout_heli"] = ("A Little Bird: miniguns and 24 rockets in salvos of 12, very fast, fragile.", "Little Bird: súng máy nhiều nòng và 24 rốc-két bắn loạt 12 quả, rất nhanh, mong manh."),
            ["note.attack_helicopter"] = ("The Apache and the Ka-52 in one card: Hellfire Longbows in pairs from 55 m, hovering at the edge of that reach, a 30 mm chain gun, rockets and Stingers for other aircraft. Drops flares.", "Apache và Ka-52 gộp một thẻ: Hellfire Longbow bắn cặp từ 55 m, treo ở rìa tầm đó, pháo 30 mm, rốc-két và Stinger bắn máy bay. Thả mồi nhiệt."),
            ["note.gunship_heli"] = ("A Mi-24P, a flying IFV: rocket pods first, a fixed 30 mm cannon, ATGMs and door gunners firing out of both sides. The heaviest helicopter, and the only one whose troops can take an objective.", "Mi-24P, xe chiến đấu bộ binh biết bay: giàn rốc-két là chính, pháo 30 mm cố định, tên lửa chống tăng và xạ thủ bắn từ hai cửa hông. Trực thăng lì nhất, và là chiếc duy nhất có lính chiếm được cứ điểm."),
            ["note.strike_drone"] = ("A Reaper: Hellfires and guided bombs from high up, long sight, slow and unarmed against aircraft.", "Reaper: Hellfire và bom dẫn đường từ trên cao, nhìn xa, chậm và không chống được máy bay."),
            ["note.attack_jet"] = ("The Su-25 and the A-10 in one card: a 30 mm cannon, 80 mm rockets and 250 kg bombs in shallow dives, two Kh-29 anti-tank missiles, R-60s to defend itself, flares. Armoured like the A-10.", "Su-25 và A-10 gộp một thẻ: pháo 30 mm, rốc-két 80 mm và bom 250 kg khi bổ nhào, hai tên lửa chống tăng Kh-29, R-60 tự vệ, mồi nhiệt. Bọc giáp như A-10."),
            ["note.ifv"] = ("A Bradley-class IFV: 30 mm cannon, coaxial gun and a TOW launcher that kills tanks; the fastest at taking points, with smoke when shot at.", "Xe chiến đấu bộ binh kiểu Bradley: pháo 30 mm, súng đồng trục và bệ TOW diệt tăng; chiếm điểm nhanh nhất, bị bắn thì thả khói."),
            ["note.command_vehicle"] = ("An 8x8 command post: friendly vehicles within 25 m fire 10% faster, and once it has stood still 5 s new vehicles land beside it. One per side.", "Sở chỉ huy 8x8: quân ta trong 25 m bắn nhanh hơn 10%, đứng yên 5 giây thì quân mới đáp xuống cạnh nó. Mỗi phe một chiếc."),
            ["note.wheeled_gun"] = ("A Centauro-style 8x8 with a 120 mm gun (the Centauro II's): fast, thin-skinned, 25% harder on a tank's flank or rear.", "Xe 8x8 kiểu Centauro với pháo 120 mm (như Centauro II): nhanh, giáp mỏng, mạnh hơn 25% khi bắn hông hoặc đuôi xe tăng."),
            ["note.armored_bulldozer"] = ("A D9-style armoured bulldozer: 3,250 health, only a roof machine gun; its blade rams structures down at three times the damage, ploughs dragon's teeth flat and takes half a mine's blast.", "Xe ủi bọc thép kiểu D9: 3.250 máu, chỉ có súng máy trên nóc; lưỡi ủi húc đổ công trình với sát thương gấp ba, ủi phẳng răng rồng và chỉ nhận một nửa sức nổ của mìn."),
            ["note.counter_battery_radar"] = ("A Cobra-style radar truck: enemy guns firing within 120 m show for 8 s, and your artillery hits them 15% harder.", "Xe radar kiểu Cobra: pháo địch khai hỏa trong 120 m bị lộ 8 giây, pháo ta bắn trúng chúng mạnh hơn 15%."),
            ["note.long_sam"] = ("An S-300-style launcher: one big missile every 8 s at aircraft out to 95 m. Nothing against the ground, nothing inside 20 m.", "Bệ phóng kiểu S-300: một tên lửa lớn mỗi 8 giây vào máy bay xa tới 95 m. Không đánh mặt đất, không bắn trong 20 m."),
            ["note.atgm_tower"] = ("A twin Kornet launcher on a tower: anti-tank missiles in pairs out to 50 m.", "Bệ Kornet đôi trên tháp: tên lửa chống tăng bắn cặp xa tới 50 m."),
            ["note.howitzer"] = ("A PzH 2000: 155 mm, the longest-range tube gun, fires three rounds fast then reloads.", "PzH 2000: 155 mm, pháo nòng tầm xa nhất, bắn nhanh ba phát rồi nạp đạn."),
            ["note.thermobaric_launcher"] = ("A TOS-1A: thermobaric rockets in salvos of 9 that level an area, but only from close in (38 m).", "TOS-1A: các loạt 9 rốc-két nhiệt áp san phẳng cả vùng, nhưng chỉ bắn gần (38 m)."),
            ["note.heavy_aa"] = ("A Tunguska: four 30 mm barrels and eight missiles; fires on the move.", "Tunguska: bốn nòng 30 mm và tám tên lửa; bắn được khi đang chạy."),
            ["note.titan_tank"] = ("A super-heavy tank: twin 140 mm guns, missiles and machine guns. Slow and very expensive.", "Siêu tăng: pháo đôi 140 mm, tên lửa và súng máy. Chậm và rất đắt."),
            ["note.heavy_bomber"] = ("A B-52: a stick of bombs along its flight line and a long-range cruise missile. Flares.", "B-52: thả một hàng bom dọc đường bay và một tên lửa hành trình tầm xa. Mồi nhiệt."),
            ["note.stealth_bomber"] = ("A B-2: huge bombs and JASSM cruise missiles from its bay. Hard to see: only close up, or just after it fires.", "B-2: bom cực lớn và tên lửa hành trình JASSM từ khoang. Khó phát hiện: chỉ thấy ở gần hoặc ngay sau khi nó bắn."),
            ["note.sky_gunship"] = ("An AC-130: circles its target anticlockwise with 105 mm, 40 mm and 25 mm guns firing out of the left side.", "AC-130: bay vòng ngược chiều kim đồng hồ quanh mục tiêu, pháo 105, 40 và 25 mm bắn từ bên trái."),
            ["note.twin_tank"] = ("The tank hunter of the heavies: two 120 mm guns fire as one volley, then a long reload. Its opening shot wins duels with thick armour. Faster than the heavy tank.", "Tăng săn tăng: hai pháo 120 mm bắn cùng lúc một loạt, rồi nạp lâu. Phát mở màn thắng tay đôi với xe giáp dày. Nhanh hơn tăng nặng."),
            ["note.siege_tank"] = ("Two modes: a 105 mm tank on the move; sieged on its braces, a 240 mm mortar that shells from outside direct-fire reach.", "Hai chế độ: xe tăng 105 mm khi di chuyển; hạ chân chống vào thế công thành thì thành cối 240 mm nã từ ngoài tầm bắn thẳng."),
            ["note.heavy_rocket_artillery"] = ("A Smerch: twelve 300 mm rockets from very far away, a long reload.", "Smerch: mười hai rốc-két 300 mm từ rất xa, nạp lại lâu."),
            ["note.ballistic_launcher"] = ("An Iskander: two ballistic missiles that hit anywhere on the map with a huge blast.", "Iskander: hai tên lửa đạn đạo đánh bất kỳ đâu trên bản đồ với vụ nổ cực lớn."),
            ["note.siege_mortar"] = ("A 240 mm mortar: one heavy bomb at a time that cracks any fortification.", "Súng cối 240 mm: từng quả bom nặng phá vỡ mọi công sự."),
            ["note.grad_truck"] = ("A Grad: forty rockets that blanket a wide area, very inaccurate, one salvo then a reload.", "Grad: bốn mươi rốc-két phủ kín một vùng rộng, rất tản mát, một loạt rồi nạp lại."),
            ["note.atgm_carrier"] = ("Fires two anti-tank missiles at once from beyond a tank's range. Thin armour.", "Bắn cùng lúc hai tên lửa chống tăng từ ngoài tầm pháo xe tăng. Giáp mỏng."),
            ["note.aps_tank"] = ("A Merkava with Trophy: shoots down missiles, rockets and drones aimed at it or beside it (not tank shells).", "Merkava có Trophy: bắn hạ tên lửa, rốc-két và drone nhắm vào nó hoặc xe bên cạnh (không chặn được đạn pháo tăng)."),
            ["note.engineer_vehicle"] = ("Repairs friendly vehicles and, at half the rate, towers around it; clears mines; breaks obstacles slowly (the bulldozer is the quick way). Keep it just behind the line.", "Sửa xe phe ta và, chậm bằng nửa, tháp phe ta xung quanh; gỡ mìn; phá vật cản chậm (xe ủi phá nhanh hơn). Giữ ngay sau tuyến đầu."),
            ["note.ammo_carrier"] = ("A forward rearm point: launchers round it reload three times as fast, helicopters beside it take their missiles and rockets on twice as fast.", "Điểm nạp tiền phương: bệ phóng quanh nó nạp nhanh gấp ba, trực thăng đậu cạnh hồi tên lửa và rốc-két nhanh gấp đôi."),
            ["note.ew_jammer"] = ("Jams the enemy in a 32 m bubble: their guided missiles, drones and fire support aimed inside go wide.", "Gây nhiễu trong vòng 32 m: tên lửa dẫn đường, drone và hỏa lực yểm trợ của địch nhắm vào trong đó bị lệch."),
            ["note.fpv_carrier"] = ("Launches swarms of FPV kamikaze drones that dive onto armour from far away.", "Phóng bầy drone FPV cảm tử lao xuống xe bọc thép từ rất xa."),
            ["note.mine_layer"] = ("Lays anti-tank mines behind it as it drives; enemies that roll over them blow up.", "Rải mìn chống tăng phía sau khi di chuyển; xe địch cán phải sẽ nổ tung."),
            ["note.fighter_jet"] = ("The air-superiority fighter: long- and short-range air-to-air missiles, hunts enemy aircraft far from its post, can hover to shoot.", "Tiêm kích chiếm ưu thế trên không: tên lửa không đối không tầm xa và gần, săn máy bay địch từ xa, có thể lơ lửng để bắn."),
            ["note.tank_buster"] = ("An A-10: the 30 mm GAU-8 shreds tanks in gun runs, Mavericks, rockets and AIM-9s for self-defence.", "A-10: pháo GAU-8 30 mm xé nát xe tăng khi bổ nhào, Maverick, rốc-két và AIM-9 tự vệ."),
            ["note.recon_drone"] = ("An unarmed spotter with the longest sight in the game, and one guided missile: eyes for your artillery.", "Drone trinh sát nhìn xa nhất trò chơi, kèm một tên lửa dẫn đường: đôi mắt cho pháo binh."),
            ["note.heavy_attack_heli"] = ("A Ka-52 Alligator: a stand-off sniper. Vikhr missiles in pairs from long range that also bring down helicopters, a 23 mm cannon and rocket pods for close work, Igla against aircraft. Coaxial rotors, flares.", "Ka-52 Alligator: bắn tỉa từ xa. Tên lửa Vikhr bắn từng cặp từ tầm xa, hạ được cả trực thăng; pháo 23 mm bên hông và giàn rốc-két khi cận chiến, Igla chống máy bay. Cánh quạt đồng trục, mồi nhiệt."),
            ["note.vbied"] = ("A car bomb in welded armour: it drives into the enemy and blows up (700 damage over 7.5 m). Shot before it arrives, it explodes where it is.", "Xe bom bọc giáp hàn: lao vào địch rồi tự nổ (700 sát thương trong bán kính 7,5 m). Bị bắn hạ trước khi tới nơi thì nổ ngay tại chỗ."),
            ["note.zu23_technical"] = ("A ZU-23-2 on a pickup: a twin 23 mm anti-aircraft gun, cheap, fast, tears up helicopters, drones and light vehicles.", "ZU-23-2 trên bán tải: pháo phòng không đôi 23 mm, rẻ, nhanh, xé nát trực thăng, drone và xe nhẹ."),
            ["note.smoke_carrier"] = ("An M58 Wolf: lays a wall of smoke around itself whenever the enemy is near, hiding the army from their guns.", "M58 Wolf: tạo màn khói quanh mình mỗi khi địch đến gần, che quân ta khỏi hỏa lực địch."),
            ["note.lancet_truck"] = ("Launches Lancet loitering munitions that fly 85 m and dive onto a target: made for artillery, SAMs and parked tanks.", "Phóng đạn bay lượn Lancet bay 85 m rồi lao xuống mục tiêu: chuyên diệt pháo, tên lửa phòng không và xe tăng đứng yên."),
            ["note.shahed_truck"] = ("Launches five slow Shahed drones that fly across the whole map at structures and defences. Loud and easy to shoot down.", "Phóng năm drone Shahed bay chậm qua cả bản đồ vào công trình và tháp phòng thủ. Ồn và dễ bị bắn hạ."),
            ["note.iron_beam"] = ("An Iron Beam laser: an endless beam at aircraft, and it shoots down rockets, missiles and drones aimed within 30 m of it. No weapon for the ground.", "La-de kiểu Iron Beam: tia bắn liên tục vào máy bay, và bắn hạ rốc-két, tên lửa, drone nhắm vào trong vòng 30 m. Không có vũ khí đánh mặt đất."),
            ["note.railgun_truck"] = ("A railgun: a slug that goes through every vehicle on its line (420 each) from 90 m. Must stand still; slow to fire.", "Pháo điện từ: viên đạn xuyên qua mọi xe trên đường bay (420 mỗi xe) từ 90 m. Phải đứng yên; bắn chậm."),
            ["note.turtle_tank"] = ("A tank under a steel shed: drones do only a fifth of their damage, its mine roller sets mines off harmlessly. The gun cannot turn: it aims with the hull.", "Xe tăng dưới mái tôn thép: drone chỉ gây 1/5 sát thương, trục lăn mìn kích nổ mìn vô hại. Pháo không xoay được: phải quay cả thân để ngắm."),
            ["note.bmpt"] = ("A BMPT Terminator: twin 30 mm cannons, Ataka missiles and grenade launchers on both front fenders firing to the sides. Escorts tanks.", "BMPT Terminator: pháo đôi 30 mm, tên lửa Ataka và súng phóng lựu hai bên chắn bùn bắn sang ngang. Hộ tống xe tăng."),
            ["note.sapper"] = ("Repairs friendly towers, turrets and bunkers around it, slowly (a tower takes a few minutes). The wrench shows over what it works on.", "Sửa chữa tháp, ụ súng và lô cốt phe ta quanh nó, chậm (một tháp mất vài phút). Biểu tượng cờ lê hiện trên công trình đang sửa."),
            ["detail.notes"] = ("ROLE", "VAI TRÒ"),
            ["detail.guide"] = ("Guide", "Hướng dẫn"),
            ["detail.firing"] = ("In action", "Xem bắn"),
            ["detail.firingNote"] = ("Live fire at targets that cannot shoot back: every weapon it carries, as in battle.", "Bắn đạn thật vào mục tiêu không bắn trả: mọi vũ khí nó mang, như trong trận đấu."),
            ["detail.firingStrike"] = ("Fire support is called on the battlefield: pick a spot and it lands there.", "Hỏa lực yểm trợ được gọi trên chiến trường: chọn một điểm và nó rơi xuống đó."),
            ["unit.silver_bug"] = ("Icarus · Orbital Spacecraft", "Icarus · Phi thuyền quỹ đạo"),
            ["short.silver_bug"] = ("Icarus", "Icarus"),
            ["unit.drop_pod"] = ("Drop pod", "Khoang đổ bộ"),
            ["short.drop_pod"] = ("Pod", "Khoang đổ bộ"),
            ["toast.enemyReinforce"] = ("Enemy reinforcements inbound!", "Địch được chi viện!"),
            ["toast.bounty"] = ("Fortress building destroyed: +{cp} CP", "Phá công trình pháo đài: +{cp} CP"),
            ["toast.escort"] = ("Boss escort destroyed: +{cp} CP", "Hạ hộ tống của boss: +{cp} CP"),
            ["toast.escortDrop"] = ("Enemy escorts are parachuting in!", "Địch đang thả dù hộ tống xuống!"),
            ["stat.razed"] = ("Buildings razed", "Công trình phá hủy"),
            ["loading.deploy"] = ("Deploying", "Xuất kích"),
            ["loading.toSea"] = ("Setting out to sea", "Ra khơi"),
            ["loading.backAshore"] = ("Back to the front", "Trở lại mặt trận"),
            ["loading.base"] = ("Returning to base", "Về căn cứ"),
            ["loading.apply"] = ("Applying settings", "Đang áp dụng cài đặt"),
            ["detail.pickTitle"] = ("Your deck", "Bộ bài của bạn"),
            ["detail.pick"] = ("Tap a card to put it in the deck or take it out; its weapons show here.", "Chạm vào thẻ để thêm vào hoặc bỏ khỏi bộ bài; vũ khí của thẻ hiện ở đây."),
            ["stat.income.boost"] = ("+{amount}/s  +{percent}%", "+{amount}/s  +{percent}%"),
