            ["mission.conquest.kicker"] = ("OPERATION 02  /  CONQUEST", "CHIẾN DỊCH 02  /  GIỮ CỨ ĐIỂM"),
            ["mission.conquest.sub"] = ("HOLD MORE POINTS THAN THE ENEMY", "GIỮ NHIỀU CỨ ĐIỂM HƠN ĐỊCH"),
            ["mission.survival.kicker"] = ("OPERATION 01  /  SURVIVAL", "CHIẾN DỊCH 01  /  SINH TỒN"),
            ["toast.conquestStart"] = ("Capture the points. Buy vehicles and strikes from the deck below.", "Chiếm cứ điểm. Mua xe và yểm trợ ở thanh bên dưới."),
            ["toast.deployed"] = ("{unit} on the way", "{unit} đang tới"),
            ["toast.captured"] = ("Point {point} captured", "Đã chiếm cứ điểm {point}"),
            ["toast.lost"] = ("Point {point} lost", "Mất cứ điểm {point}"),
            ["toast.enemyStrike"] = ("Enemy {support} incoming!", "Địch gọi {support}!"),
            ["toast.airDefence"] = ("Enemy aircraft: bring anti-air", "Máy bay địch: hãy dùng xe phòng không"),
            ["target.hint"] = ("Tap the battlefield to call {support}", "Chạm vào chiến trường để gọi {support}"),
            ["target.cancel"] = ("Cancel", "Hủy"),
            ["err.UnknownCard"] = ("Not in your deck", "Không có trong bộ bài"),
            ["err.NotEnoughCp"] = ("Not enough CP", "Không đủ CP"),
            ["err.ArmyAtCapacity"] = ("Too many vehicles on the field", "Quá nhiều xe trên chiến trường"),
            ["err.AirAtCapacity"] = ("Air slots full: at most 6 aircraft at once", "Hết suất không quân: tối đa 6 máy bay cùng lúc"),
            ["err.OnCooldown"] = ("Not ready yet", "Chưa sẵn sàng"),
            ["err.UnitLimit"] = ("Only one of these per side", "Mỗi phe chỉ được một chiếc"),
            ["unit.ew_tower"] = ("EW tower", "Tháp gây nhiễu EW"),
            ["unit.dragons_teeth"] = ("Dragon's teeth", "Răng rồng"),
            ["unit.minefield"] = ("Minefield", "Bãi mìn"),
            ["unit.c_ram"] = ("C-RAM interceptor", "Trạm đánh chặn C-RAM"),
            ["unit.gun_pit"] = ("Hidden gun pit", "Ụ pháo ẩn"),
            ["unit.drone_hangar"] = ("Drone hangar", "Nhà chứa drone"),
            ["unit.repair_bay"] = ("Repair bay", "Xưởng sửa chữa"),
            ["unit.ammo_depot"] = ("Ammunition depot", "Kho đạn"),
            ["unit.airfield"] = ("Airfield", "Sân bay dã chiến"),
            ["unit.logistics_station"] = ("Logistics station", "Trạm hậu cần"),
            ["unit.radar_station"] = ("Radar station", "Trạm radar"),
            ["branch.guard_tower.watch"] = ("Watchtower", "Tháp quan sát"),
            ["branch.guard_tower.watch.info"] = ("Sees 30% further, and lends towers within 30 m 15% more range.", "Nhìn xa hơn 30%, và cho các tháp trong 30 m thêm 15% tầm bắn."),
            ["branch.guard_tower.nest"] = ("Gun nest", "Ổ súng"),
            ["branch.guard_tower.nest.info"] = ("A 25 mm cannon for the machine gun: hits light vehicles hard, sees less far.", "Pháo 25 mm thay súng máy: đánh mạnh xe nhẹ, nhìn gần hơn."),
            ["branch.mg_bunker.twin"] = ("Twin HMG", "Súng máy đôi"),
            ["branch.mg_bunker.twin.info"] = ("Twin heavy machine guns: more fire, a little less reach.", "Súng máy nặng đôi: hỏa lực mạnh hơn, tầm hơi ngắn hơn."),
            ["branch.mg_bunker.flame"] = ("Flame bunker", "Lô cốt phun lửa"),
            ["branch.mg_bunker.flame.info"] = ("A flamethrower (16 m) that burns what gets close; nothing against aircraft.", "Súng phun lửa (16 m) đốt thứ gì lại gần; không bắn được máy bay."),
            ["branch.ew_tower.drone"] = ("Drone jammer", "Máy gây nhiễu drone"),
            ["branch.ew_tower.drone.info"] = ("Jams guided rounds and drones out to 45 m.", "Gây nhiễu đạn điều khiển và drone xa tới 45 m."),
            ["branch.ew_tower.spoof"] = ("Radar spoofer", "Máy đánh lừa radar"),
            ["branch.ew_tower.spoof.info"] = ("Also finds the guns that fire within 80 m and shows them for 6 s.", "Còn tìm ra pháo khai hỏa trong 80 m và làm lộ chúng 6 giây."),
            ["branch.dragons_teeth.hedgehog"] = ("Hedgehogs", "Chông sắt"),
            ["branch.dragons_teeth.hedgehog.info"] = ("Twice as tough to breach.", "Khó phá gấp đôi."),
            ["branch.dragons_teeth.wire"] = ("Wire and ditch", "Rào thép gai"),
            ["branch.dragons_teeth.wire.info"] = ("Does not block the way, but slows enemy vehicles within 6 m by half.", "Không chặn đường, nhưng làm xe địch trong 6 m chậm một nửa."),
            ["branch.minefield.at"] = ("Anti-tank field", "Bãi mìn chống tăng"),
            ["branch.minefield.at.info"] = ("Five mines that hit 60% harder.", "Năm quả mìn mạnh hơn 60%."),
            ["branch.minefield.scatter"] = ("Scatter field", "Bãi mìn rải"),
            ["branch.minefield.scatter.info"] = ("Ten lighter mines over a wider field, laid again sooner.", "Mười quả mìn nhẹ hơn trên diện rộng hơn, rải lại nhanh hơn."),
            ["branch.gun_turret.long"] = ("Sniper gun", "Pháo bắn tỉa"),
            ["branch.gun_turret.long.info"] = ("A long 120 mm with a sight: reaches further than any tank gun, slow, every round a tank-killer; no aircraft.", "Pháo 120 mm nòng dài có ống ngắm: bắn xa hơn mọi pháo xe tăng, chậm, mỗi phát hạ được xe tăng; không bắn máy bay."),
            ["branch.gun_turret.auto"] = ("57 mm autocannon", "Pháo tự động 57 mm"),
            ["branch.gun_turret.auto.info"] = ("Fast bursts, hard on light vehicles; air-burst rounds for helicopters, aircraft and drones; poor on thick armour.", "Bắn loạt nhanh, mạnh với xe nhẹ; đạn nổ trên không cho trực thăng, máy bay và drone; yếu với giáp dày."),
            ["branch.atgm_tower.top"] = ("Top attack", "Tấn công từ trên"),
            ["branch.atgm_tower.top.info"] = ("40% harder on heavy armour.", "Mạnh hơn 40% lên giáp dày."),
            ["branch.atgm_tower.multi"] = ("Multi-role", "Đa năng"),
            ["branch.atgm_tower.multi.info"] = ("Also shoots helicopters and aircraft; lighter on armour.", "Bắn được cả trực thăng và máy bay; nhẹ hơn lên giáp."),
            ["branch.rocket_turret.cluster"] = ("Cluster rockets", "Rốc-két chùm"),
            ["branch.rocket_turret.cluster.info"] = ("Each rocket scatters bomblets: better on groups, lighter direct hits.", "Mỗi rốc-két rải bom con: tốt hơn với cụm quân, trúng trực tiếp nhẹ hơn."),
            ["branch.c_ram.centurion"] = ("Centurion", "Centurion"),
            ["branch.c_ram.centurion.info"] = ("The quick close-in gun: more interceptors, back fast; takes direct fire too.", "Súng đánh chặn tầm gần bắn nhanh: nhiều quả đánh chặn hơn, hồi nhanh; chặn cả đạn bắn thẳng."),
            // Prompt 20 L.1: the Iron Dome replaces the Hunter.
            ["branch.c_ram.dome"] = ("Iron Dome", "Vòm Sắt"),
            ["branch.c_ram.dome.info"] = ("Interceptor missiles instead of the gatling: shoots down rockets, half the shells, drones and long-range missiles aimed within 60 m; six in the launcher, 12 s to reload. No direct fire or energy.",
                "Tên lửa đánh chặn thay cho súng nhiều nòng: bắn hạ rốc-két, một nửa số đạn pháo, drone và tên lửa tầm xa nhắm vào trong 60 m; sáu quả trong bệ phóng, nạp lại 12 giây. Không chặn đạn bắn thẳng và Năng lượng."),
            ["branch.gun_pit.ambush"] = ("Ambush", "Phục kích"),
            ["branch.gun_pit.ambush.info"] = ("Its first shot after rising hits twice as hard.", "Phát bắn đầu tiên sau khi trồi lên mạnh gấp đôi."),
            ["branch.gun_pit.deep"] = ("Deep pit", "Hầm sâu"),
            ["branch.gun_pit.deep.info"] = ("Takes 75% less damage while down; rises only for enemies within 30 m.", "Chịu ít hơn 75% sát thương khi ẩn; chỉ trồi lên khi địch trong 30 m."),
            ["branch.artillery_emplacement.cb"] = ("Counter-battery", "Phản pháo"),
            ["branch.artillery_emplacement.cb.info"] = ("Goes for enemy guns the moment they fire in its reach and shows them for a while; hits artillery harder.", "Nhắm ngay pháo địch vừa khai hỏa trong tầm và làm lộ chúng một lúc; đánh pháo binh mạnh hơn."),
            ["branch.missile_battery.pac3"] = ("PAC-3 interceptor", "PAC-3 đánh chặn"),
            ["branch.missile_battery.pac3.info"] = ("Shoots down cruise and ballistic missiles, cruise-missile strikes and a boss's missile attacks; weaker on aircraft.", "Bắn hạ tên lửa hành trình, tên lửa đạn đạo, đòn tên lửa hành trình và tên lửa từ đòn lớn của boss; bắn máy bay yếu hơn."),
            ["branch.missile_battery.lrr"] = ("Long-range radar", "Radar tầm xa"),
            ["branch.missile_battery.lrr.info"] = ("Hits aircraft from very far and shows every enemy aircraft over a wide circle; intercepts no missiles.", "Bắn máy bay từ rất xa và làm lộ mọi máy bay địch trong vùng rộng; không đánh chặn tên lửa."),
            ["branch.drone_hangar.lancet"] = ("Lancet hangar", "Nhà chứa Lancet"),
            ["branch.drone_hangar.lancet.info"] = ("Lancet loitering munitions instead of FPV drones: far reach, double on artillery and parked vehicles.", "Đạn bay lượn Lancet thay drone FPV: tầm xa, gấp đôi lên pháo binh và xe đỗ."),
            ["branch.drone_hangar.swarm"] = ("Swarm", "Bầy đàn"),
            ["branch.drone_hangar.swarm.info"] = ("Bigger flights of FPV drones, less often.", "Những đợt drone FPV đông hơn, thưa hơn."),
            ["branch.heavy_turret.coastal"] = ("Long-range coastal battery", "Pháo bờ biển tầm xa"),
            ["branch.heavy_turret.coastal.info"] = ("Its 155 mm guns reach 72 m. Opened by sinking Leviathan (4-11).", "Pháo 155 mm bắn tới 72 m. Mở khi đánh chìm Leviathan (4-11)."),
            ["branch.heavy_turret.bastion"] = ("Steel fortress", "Pháo đài thép"),
            ["branch.heavy_turret.bastion.info"] = ("Much tougher, with two small machine-gun turrets all round for cars and drones up close.", "Chắc hơn nhiều, thêm hai tháp súng máy nhỏ xoay quanh đánh xe nhẹ và drone áp sát."),
            ["branch.aa_turret.flak"] = ("Flak tower", "Tháp cao xạ"),
            ["branch.aa_turret.flak.info"] = ("Quad 23 mm flak close in: far more fire at drones, small swarms and helicopters, no missiles.", "Pháo cao xạ 23 mm bốn nòng tầm gần: hỏa lực mạnh hơn nhiều vào drone, bầy nhỏ và trực thăng, không có tên lửa."),
            ["branch.airfield.hangar"] = ("Hangar", "Nhà chứa máy bay"),
            ["branch.airfield.hangar.info"] = ("One more aircraft up at once, a little tougher.", "Thêm một máy bay cùng lúc, chắc hơn một chút."),
            ["branch.airfield.service"] = ("Fast service", "Phục vụ nhanh"),
            ["branch.airfield.service.info"] = ("Aircraft over it rearm and mend half as fast again.", "Máy bay trên nó hồi đạn và hồi máu nhanh thêm một nửa."),
            // The tower-branch rework (DECISIONS 19T): new branches, when to pick each, the picker's words, the news.
            ["branch.rocket_turret.guided"] = ("Guided rockets", "Rốc-két dẫn đường"),
            ["branch.rocket_turret.guided.info"] = ("Two precise GMLRS rockets at long range: hard on artillery and buildings, poor against a swarm of small vehicles.", "Hai rốc-két GMLRS chính xác ở tầm xa: mạnh với pháo binh và công trình, yếu trước bầy xe nhỏ."),
            ["branch.artillery_emplacement.mortar"] = ("Heavy mortar", "Cối hạng nặng"),
            ["branch.artillery_emplacement.mortar.info"] = ("A 240 mm on a high arc, over walls into yards and behind cover: short reach, small minimum range, a huge blast, hard on buildings.", "Cối 240 mm bắn cầu vồng, qua tường vào sân trong và sau vật che: tầm ngắn, tầm tối thiểu nhỏ, nổ lan rất lớn, mạnh với công trình."),
            ["branch.shield_tower.ward"] = ("Tower shields", "Lá chắn tháp"),
            ["branch.shield_tower.ward.info"] = ("No dome: every tower of yours around it has a small shield of its own that stops rounds aimed at it (not blasts round it), back a few seconds after its last hit. Energy goes through; never on top of a dome.", "Không có vòm chung: mỗi tháp phe ta quanh nó có một khiên nhỏ riêng chặn đạn bắn trúng nó (không chặn vụ nổ xung quanh), tự hồi sau vài giây không bị trúng. Đạn Năng lượng vẫn xuyên qua; không cộng dồn với vòm khiên."),
            ["branch.cp_relay.loot"] = ("Loot depot", "Kho chiến lợi phẩm"),
            ["branch.cp_relay.loot.info"] = ("No steady CP: every enemy vehicle destroyed near it pays a share of its price (never past the kill refund cap).", "Không thêm CP đều: mỗi xe địch bị hạ gần nó cho thêm CP theo giá xe (không vượt trần hoàn CP)."),
            ["branch.guard_tower.watch.when"] = ("Towers around it need reach, or the enemy hides stealth units.", "Các tháp quanh nó cần thêm tầm, hoặc địch có quân tàng hình."),
            ["branch.guard_tower.nest.when"] = ("A stream of light vehicles comes at this side.", "Xe nhẹ liên tục đánh vào phía này."),
            ["branch.mg_bunker.twin.when"] = ("Light vehicles and helicopters come in numbers.", "Xe nhẹ và trực thăng đến đông."),
            ["branch.mg_bunker.flame.when"] = ("Enemies get close: a gate, a corner, a narrow way in.", "Địch áp sát: cổng, góc khuất, lối vào hẹp."),
            ["branch.ew_tower.drone.when"] = ("Drones and guided missiles are the threat.", "Mối đe dọa là drone và tên lửa điều khiển."),
            ["branch.ew_tower.spoof.when"] = ("Enemy artillery shells the base from out of sight.", "Pháo binh địch nã vào căn cứ từ ngoài tầm nhìn."),
            ["branch.dragons_teeth.hedgehog.when"] = ("Bulldozers and engineers break the way in.", "Xe ủi và công binh phá đường vào."),
            ["branch.dragons_teeth.wire.when"] = ("You want the way open but slowed under your guns.", "Muốn để ngỏ lối đi nhưng làm chậm dưới họng súng ta."),
            ["branch.minefield.at.when"] = ("Tanks come down this road.", "Xe tăng đi theo đường này."),
            ["branch.minefield.scatter.when"] = ("Many light vehicles come over wide ground.", "Nhiều xe nhẹ đến trên địa hình rộng."),
            ["branch.gun_turret.long.when"] = ("Tanks and tank hunters come at the base.", "Xe tăng và xe săn tăng đánh vào căn cứ."),
            ["branch.gun_turret.auto.when"] = ("Light vehicles, helicopters and drones come at the base.", "Xe nhẹ, trực thăng và drone đánh vào căn cứ."),
            ["branch.atgm_tower.top.when"] = ("Heavy armour leads the attack.", "Giáp dày dẫn đầu đợt tấn công."),
            ["branch.atgm_tower.multi.when"] = ("Helicopters come with the tanks.", "Trực thăng đi cùng xe tăng."),
            ["branch.rocket_turret.cluster.when"] = ("Groups of vehicles bunch up at the gates.", "Cụm xe dồn lại trước cổng."),
            ["branch.rocket_turret.guided.when"] = ("Enemy artillery or buildings in the enemy camp are in reach.", "Pháo binh địch hoặc công trình trại địch trong tầm."),
            ["branch.c_ram.centurion.when"] = ("ATGMs, rocket pods and helicopters' missiles fly straight at the base.", "Tên lửa chống tăng, rốc-két bắn thẳng và tên lửa trực thăng nhắm vào căn cứ."),
            ["branch.c_ram.dome.when"] = ("Artillery rockets, shells, drones and long-range missiles rain on the base.", "Rốc-két pháo binh, đạn pháo, drone và tên lửa tầm xa dội vào căn cứ."),
            ["branch.artillery_emplacement.cb.when"] = ("The enemy brings artillery.", "Địch mang theo pháo binh."),
            ["branch.artillery_emplacement.mortar.when"] = ("Enemies take cover behind walls, or the fight is close to the base.", "Địch nấp sau tường, hoặc giao tranh sát căn cứ."),
            ["branch.missile_battery.pac3.when"] = ("Bombers, missile launchers or a boss with missile attacks.", "Máy bay ném bom, bệ phóng tên lửa hoặc boss có đòn tên lửa."),
            ["branch.missile_battery.lrr.when"] = ("Many aircraft, or stealth aircraft you cannot see.", "Nhiều máy bay, hoặc máy bay tàng hình không nhìn thấy."),
            ["branch.drone_hangar.lancet.when"] = ("Enemy artillery and parked vehicles.", "Pháo binh và xe đỗ của địch."),
            ["branch.drone_hangar.swarm.when"] = ("Armour in the open.", "Xe bọc thép ngoài bãi trống."),
            ["branch.heavy_turret.coastal.when"] = ("Targets far off: ships, artillery, a long approach.", "Mục tiêu ở xa: tàu, pháo binh, đường tiếp cận dài."),
            ["branch.heavy_turret.bastion.when"] = ("Cars and drones swarm round it.", "Xe nhẹ và drone vây quanh nó."),
            ["branch.aa_turret.flak.when"] = ("Drones and helicopters come low and close.", "Drone và trực thăng bay thấp, áp sát."),
            ["branch.aa_turret.sam.when"] = ("Aircraft attack from middle range.", "Máy bay tấn công từ tầm trung."),
            ["branch.shield_tower.bulwark.when"] = ("Barrages and big blasts over the whole base.", "Loạt pháo và vụ nổ lớn phủ cả căn cứ."),
            ["branch.shield_tower.ward.when"] = ("The enemy focuses its fire on one tower at a time.", "Địch dồn hỏa lực vào từng tháp."),
            ["branch.cp_relay.hardened.when"] = ("The base is quiet and you want steady CP.", "Căn cứ yên ổn và cần CP đều đặn."),
            ["branch.cp_relay.loot.when"] = ("The base is attacked again and again.", "Căn cứ bị tấn công liên tục."),
            ["detail.branches"] = ("Branches (rank 7)", "Nhánh (hạng 7)"),
            ["branch.when"] = ("Pick it when: {branch}", "Nên chọn khi: {branch}"),
            ["branch.range"] = ("Reach {metres} m", "Tầm {metres} m"),
            ["branch.targets"] = ("Hits: {air}", "Bắn: {air}"),
            ["branch.targets.ground"] = ("ground", "mặt đất"),
            ["branch.targets.air"] = ("aircraft", "máy bay"),
            ["branch.targets.all"] = ("ground and aircraft", "mặt đất và máy bay"),
            ["branch.targets.none"] = ("nothing (no gun)", "không (không có súng)"),
            ["branch.mech.intercepts"] = ("Intercepts: {direct}", "Đánh chặn: {direct}"),
            ["branch.mech.heavy"] = ("cruise and ballistic missiles, boss missiles", "tên lửa hành trình, đạn đạo, tên lửa của boss"),
            ["branch.mech.lobbed"] = ("rockets, shells, drones, long-range missiles", "rốc-két, đạn pháo, drone, tên lửa tầm xa"),
            ["branch.mech.direct"] = ("rockets, missiles and direct fire", "rốc-két, tên lửa và đạn bắn thẳng"),
            ["branch.mech.dome"] = ("Dome {metres} m, {count|# hit point|# hit points}", "Vòm {metres} m, {count} điểm bền"),
            ["branch.mech.wards"] = ("A shield on every tower within {metres} m ({health} each, back {seconds} s after a hit)", "Khiên riêng cho mọi tháp trong {metres} m ({health} mỗi tháp, hồi sau {seconds} giây)"),
            ["branch.mech.loot"] = ("{percent}% of each enemy vehicle destroyed within {metres} m", "{percent}% giá mỗi xe địch bị hạ trong {metres} m"),
            ["branch.mech.relay"] = ("+{cp} CP a second", "+{cp} CP mỗi giây"),
            ["branch.mech.revealAir"] = ("Shows enemy aircraft within {metres} m", "Làm lộ máy bay địch trong {metres} m"),
            ["branch.mech.counterBattery"] = ("Finds guns firing within {metres} m", "Tìm ra pháo khai hỏa trong {metres} m"),
            ["branch.mech.overWalls"] = ("Fires over walls", "Bắn qua tường"),
            ["branch.mech.mines"] = ("{count|# mine|# mines} of {damage}", "{count} quả mìn, mỗi quả {damage}"),
            ["branch.mech.jammer"] = ("Jams within {metres} m", "Gây nhiễu trong {metres} m"),
            ["branch.mech.hp"] = ("Health {maxHp}", "Máu {maxHp}"),
            ["news.branches.title"] = ("Tower branches changed", "Nhánh tháp đã thay đổi"),
            ["news.branches"] = ("Rank-7 branches were remade: {names}. Your choice moved to the nearest new branch, and your next change on these towers is free.", "Nhánh hạng 7 đã được làm lại: {names}. Lựa chọn của bạn đã chuyển sang nhánh mới gần nhất, và lần đổi nhánh tiếp theo của các tháp này được miễn phí."),
            // DECISIONS 23D: an old save's doctrines refunded (shown once).
            ["news.refund.title"] = ("Coins refunded", "Đã hoàn xu"),
            ["news.refund"] = ("The doctrines are now part of the commanders: each commander carries the edge that suits its style. The {coins|# coin|# coins} you paid for doctrines are back in your purse.",
                "Các học thuyết nay đã gộp vào chỉ huy: mỗi chỉ huy mang lợi thế hợp với lối đánh của mình. {coins} xu bạn đã trả cho học thuyết đã được hoàn lại."),
            ["camp.branchFreeSwap"] = ("The branches were remade: your next change is free.", "Nhánh đã được làm lại: lần đổi tiếp theo miễn phí."),
            ["branch.aa_turret.sam"] = ("SAM post", "Trạm tên lửa"),
            ["branch.aa_turret.sam.info"] = ("A 60 m SAM pair instead of the flak: for aircraft and helicopters at middle range (the long-range SAM site reaches furthest); fires less.", "Cặp tên lửa phòng không 60 m thay cho pháo cao xạ: đánh máy bay và trực thăng ở tầm trung (trạm PK tầm xa bắn xa nhất); ít phát hơn."),
