            ["ops.title"] = ("Operations", "Tác chiến"),
            ["ops.sub"] = ("The big operations and the story's great battles, again: four tiers, a score, your records.", "Các chiến dịch lớn và những trận đánh lớn của cốt truyện, chơi lại: bốn cấp độ, tính điểm, kỷ lục của bạn."),
            ["ops.score"] = ("Score", "Điểm"),
            ["ops.best"] = ("Best", "Kỷ lục"),
            ["ops.newRecord"] = ("New record!", "Kỷ lục mới!"),
            ["ops.mutators"] = ("Mutators", "Biến thể"),
            ["ops.weekly"] = ("This week's operation", "Chiến dịch của tuần"),
            ["ops.weeklySub"] = ("With {mutator} and {mutator2}. First win this week: {coins|# coin|# coins}.", "Kèm {mutator} và {mutator2}. Thắng lần đầu trong tuần: {coins} xu."),
            ["ops.locked"] = ("Win it in the campaign to play it here.", "Thắng trận này trong chiến dịch để mở ở đây."),
            ["ops.none"] = ("The big operations open here as you win them in the campaign.", "Các chiến dịch lớn sẽ mở ở đây khi bạn thắng chúng trong chiến dịch."),
            ["ops.legendLocked"] = ("Legend opens once the campaign's last operation is won.", "Cấp Huyền thoại mở sau khi thắng chiến dịch lớn cuối cùng."),
            ["ops.resultTitle"] = ("{title} · {tier}", "{title} · {tier}"),
            ["mutator.storm"] = ("Stormy night", "Đêm bão"),
            ["mutator.storm.info"] = ("The battle is fought in a storm.", "Trận đánh diễn ra trong bão."),
            ["mutator.enemy_air"] = ("All-air enemy", "Địch toàn không quân"),
            ["mutator.enemy_air.info"] = ("The enemy fields aircraft only.", "Địch chỉ dùng máy bay và trực thăng."),
            ["mutator.no_support"] = ("No fire support", "Không hỏa lực"),
            ["mutator.no_support.info"] = ("You go without fire support cards.", "Bạn không có thẻ hỏa lực yểm trợ."),
            ["mutator.two_bosses"] = ("Extra mini boss", "Thêm mini boss"),
            ["mutator.two_bosses.info"] = ("A mini boss of the chapter's general comes out of the enemy's camp as well (on a boss battle, that boss's mini version).", "Thêm một mini boss của tướng chương này xuất hiện từ căn cứ địch (ở trận có boss: bản mini của boss đó)."),
            ["mutator.towers_x2"] = ("Enemy towers x2", "Tháp địch ×2"),
            ["mutator.towers_x2.info"] = ("Enemy towers have double health and hit 50% harder.", "Tháp địch gấp đôi máu và bắn mạnh hơn 50%."),
            ["mutator.no_repair"] = ("No repairs", "Không có trạm sửa chữa"),
            ["mutator.no_repair.info"] = ("No repair bay in your base, no repair drops.", "Căn cứ không có xưởng sửa chữa, không có thả sửa chữa."),
            ["mutator.general_boost"] = ("Reinforced general", "Tướng địch tăng cường"),
            ["mutator.general_boost.info"] = ("The enemy starts with 50% more CP and earns 30% more.", "Địch khởi đầu nhiều hơn 50% CP và thu nhập cao hơn 30%."),
            ["mutator.light_deck"] = ("Under 8 CP", "Chỉ dùng xe dưới 8 CP"),
            ["mutator.light_deck.info"] = ("You may only field vehicles that cost less than 8 CP.", "Bạn chỉ được dùng xe có giá dưới 8 CP."),
            ["mutator.armour_only"] = ("Armour only", "Chỉ thiết giáp"),
            ["mutator.armour_only.info"] = ("You may only field heavy armour.", "Bạn chỉ được dùng xe giáp nặng."),
            ["mutator.no_air"] = ("Grounded", "Cấm không quân"),
            ["mutator.no_air.info"] = ("Neither side may field aircraft.", "Không bên nào được dùng máy bay."),
            ["mutator.glass_cannon"] = ("Glass cannons", "Pháo giấy"),
            ["mutator.glass_cannon.info"] = ("Everything hits 50% harder and has a quarter less health.", "Mọi xe bắn mạnh hơn 50% và ít hơn một phần tư máu."),
            ["mutator.veterans"] = ("Veteran enemy", "Địch lão luyện"),
            ["mutator.veterans.info"] = ("Enemy vehicles have 25% more health.", "Xe địch nhiều hơn 25% máu."),
            ["mutator.time_attack"] = ("Against the clock", "Chạy đua thời gian"),
            ["mutator.time_attack.info"] = ("The time limit is 30% shorter (25 minutes where there was none).", "Giới hạn thời gian ngắn hơn 30% (25 phút nếu trước đó không có)."),
            ["mutator.lean_logistics"] = ("Lean logistics", "Hậu cần cạn kiệt"),
            ["mutator.lean_logistics.info"] = ("You earn a quarter less CP.", "Thu nhập CP của bạn giảm một phần tư."),
            ["mutator.sea_storm"] = ("Sea storm", "Bão biển"),
            ["mutator.sea_storm.info"] = ("A storm, and thick fog on the sea: ships are seen from much closer in.", "Có bão, sương mù dày trên mặt biển: phải tới gần hơn nhiều mới thấy tàu."),
            ["mutator.fleet"] = ("Fleet", "Hạm đội"),
            ["mutator.fleet.info"] = ("A flagship sails with one more escort and two more attack boats; the enemy earns 10% more.", "Tàu chính có thêm một tàu hộ vệ và hai xuồng tên lửa; thu nhập của địch tăng 10%."),
            ["mutator.iron_rain"] = ("Iron rain", "Mưa bom"),
            ["mutator.iron_rain.info"] = ("Bomber raids hit the thickest fighting, on both sides.", "Máy bay ném bom đánh vào nơi giao tranh dày đặc nhất, cả hai phe."),
            ["mutator.swarm"] = ("Swarm", "Bầy đàn"),
            ["mutator.swarm.info"] = ("The enemy's reinforcements come twice as many, in cheap swarms.", "Quân tiếp viện của địch đông gấp đôi, đi thành bầy xe rẻ."),
            ["mutator.empty_base"] = ("Empty base", "Căn cứ trống"),
            ["mutator.empty_base.info"] = ("Your base has its HQ and no towers.", "Căn cứ của bạn chỉ có sở chỉ huy, không có tháp."),
            ["mutator.night_ops"] = ("Night operation", "Tác chiến đêm"),
            ["mutator.night_ops.info"] = ("The battle is fought at night.", "Trận đánh diễn ra vào ban đêm."),
            ["boss.transforming"] = ("Transforming", "Đang biến hình"),
            ["boss.escaping"] = ("Escaping {time}", "Đang thoát {time}"),
            ["toast.bossPhase"] = ("{card} changes form: phase {phase}!", "{card} biến hình: pha {phase}!"),
            ["result.stages"] = ("Stages done", "Giai đoạn đã xong"),
            ["loading.checkpoint"] = ("Back to the checkpoint", "Về điểm lưu"),
            ["stage.kicker"] = ("Stage {stage}", "Giai đoạn {stage}"),
            ["stage.goal"] = ("Stage {stage} · {goalText}", "Giai đoạn {stage} · {goalText}"),
            ["choice.title"] = ("Choose the way on", "Chọn hướng tiến công"),
            ["choice.auto"] = ("The first is taken in {seconds} s", "Tự chọn phương án đầu sau {seconds} giây"),
            ["radio.elite"] = ("Recon: enemy {card} on the field, ringed in gold: focus it.", "Trinh sát: {card} của địch ra trận, có vòng vàng: dồn hỏa lực."),
            ["result.elites"] = ("Elites destroyed", "Tinh nhuệ bị hạ"),
            ["result.elitesValue"] = ("{baseCards} (+{coins|# coin|# coins})", "{baseCards} (+{coins} xu)"),
            ["result.blueprint"] = ("Blueprint found", "Nhặt được bản thiết kế"),
            ["detail.eliteVersion"] = ("The enemy's elite version", "Bản tinh nhuệ của địch"),
            ["radio.betrayal"] = ("The allied commander has turned on us: their units are firing on ours!", "Chỉ huy đồng minh đã trở mặt: quân của họ đang bắn vào ta!"),
            ["radio.kessler.supergun"] = ("Kessler: \"My gun reaches every corner of this field. Scatter, and it still finds you.\"", "Kessler: \"Pháo của ta với tới mọi góc chiến trường. Tản ra thì nó vẫn tìm được các ngươi.\""),
            ["radio.kessler.supergun.half"] = ("Kessler: \"Reload faster! Bring the heavy charges!\"", "Kessler: \"Nạp nhanh lên! Đem liều phóng nặng ra!\""),
            ["radio.varga.borer"] = ("Varga: \"You watch the horizon. My Worm comes from below.\"", "Varga: \"Các ngươi canh chân trời. Tartarus của ta đến từ dưới chân.\""),
            ["radio.varga.borer.half"] = ("Varga: \"Dig deeper. Break them from underneath!\"", "Varga: \"Khoan sâu hơn. Phá chúng từ bên dưới!\""),
            ["radio.quaden.airship"] = ("Wolff: \"Look up. The sky over this field is mine.\"", "Wolff: \"Nhìn lên đi. Bầu trời trên chiến trường này là của ta.\""),
            ["radio.quaden.airship.half"] = ("Wolff: \"All bays open. Drown them in drones!\"", "Wolff: \"Mở hết cửa nhà chứa. Nhấn chìm chúng bằng drone!\""),
            ["radio.kessler.hovercraft"] = ("Kessler: \"The landing force is under way. Hold the beach and they cannot stop us.\"", "Kessler: \"Lực lượng đổ bộ đã lên đường. Giữ được bãi biển là chúng không cản nổi.\""),
            ["radio.kessler.leviathan"] = ("Kessler: \"Leviathan is on station. The whole coast is in reach, and none of it can reach me.\"", "Kessler: \"Leviathan đã vào vị trí. Cả dải bờ biển nằm trong tầm, còn không thứ gì với tới ta.\""),
            ["radio.kessler.leviathan.phase2"] = ("Kessler: \"Close in. Open the well deck, launch the helicopters. Pin them to the beach.\"", "Kessler: \"Áp sát vào. Mở khoang đổ bộ, cho trực thăng cất cánh. Dồn chúng xuống bãi biển.\""),
            ["radio.kessler.leviathan.phase3"] = ("Kessler: \"Empty the cells on their HQ. Smoke, full ahead: we are leaving.\"", "Kessler: \"Phóng hết tên lửa vào sở chỉ huy của chúng. Thả khói, hết tốc lực: ta rút.\""),
            ["radio.kessler.leviathan.run"] = ("Command: Leviathan is running for open sea behind its smoke. Sink it before it gets away!", "Chỉ huy: Leviathan đang chạy ra khơi sau màn khói. Đánh chìm nó trước khi nó thoát!"),
            ["radio.kessler.leviathan.escaped"] = ("Kessler: \"Out of range, Colonel. The sea was always mine.\"", "Kessler: \"Ra khỏi tầm rồi, đại tá. Biển xưa nay vẫn là của ta.\""),
            ["radio.kessler.leviathan.sunk"] = ("Kessler: \"Abandon ship... Log the time. Somebody log the time.\"", "Kessler: \"Bỏ tàu... Ghi lại giờ. Ai đó ghi lại giờ đi.\""),
            ["radio.naval.battery.ours"] = ("Command: the coastal battery is ours. Its guns are turning on the fleet.", "Chỉ huy: trận địa pháo bờ biển đã về tay ta. Pháo đang quay về phía hạm đội."),
            ["radio.naval.battery.theirs"] = ("Command: the enemy has taken a coastal battery.", "Chỉ huy: địch đã chiếm một trận địa pháo bờ biển."),
            ["radio.naval.lighthouse.ours"] = ("Command: we hold the lighthouse. Every ship out there is on our plot now.", "Chỉ huy: ta đã giữ ngọn hải đăng. Mọi con tàu ngoài kia giờ đều hiện trên bản đồ của ta."),
            ["radio.naval.lighthouse.theirs"] = ("Command: the enemy holds the lighthouse.", "Chỉ huy: địch đang giữ ngọn hải đăng."),
            ["radio.part.vls"] = ("Command: {boss}'s missile cells are wrecked. No more cruise missiles!", "Chỉ huy: ống phóng tên lửa của {boss} đã bị phá. Hết tên lửa hành trình!"),
            ["radio.part.ciws"] = ("Command: {boss}'s last CIWS is down. Missiles and drones get through now!", "Chỉ huy: cụm CIWS cuối của {boss} đã tắt. Tên lửa và drone giờ đánh trúng được rồi!"),
            ["radio.part.radar"] = ("Command: {boss}'s radar mast is down. Its shells go wide, its CIWS misses.", "Chỉ huy: cột radar của {boss} đã đổ. Đạn pháo rơi lệch, CIWS bắn trượt."),
            ["radio.part.flightdeck"] = ("Command: {boss}'s flight deck is burning. No more helicopters off it.", "Chỉ huy: sàn đáp của {boss} đang cháy. Hết trực thăng cất cánh từ đó."),
            ["radio.part.welldeck"] = ("Command: {boss}'s well deck is wrecked. No more landing craft.", "Chỉ huy: khoang đổ bộ của {boss} đã hỏng. Hết tàu đổ bộ."),
            ["radio.part.machinery"] = ("Command: {boss}'s engine room is hit! It is losing way: it cannot outrun us now.", "Chỉ huy: buồng máy của {boss} trúng đòn! Nó đang chậm lại: hết đường chạy thoát."),
            ["radio.kessler.hovercraft.half"] = ("Kessler: \"Full throttle, land everything we have!\"", "Kessler: \"Hết tốc lực, đổ bộ toàn bộ lực lượng!\""),
            ["radio.hung.supreme"] = ("{@lyhan}: \"You trusted me once. Now my whole army fights harder for it.\"", "{@lyhan}: \"Các người từng tin ta. Giờ cả đạo quân của ta đánh mạnh hơn nhờ điều đó.\""),
            ["radio.hung.supreme.half"] = ("{@lyhan}: \"Guard, to me! Protect the command!\"", "{@lyhan}: \"Cận vệ, lại đây! Bảo vệ sở chỉ huy!\""),
            ["toast.partBroken"] = ("{name}: {kills} destroyed", "{name}: đã phá {kills}"),
            ["toast.burrow"] = ("The Tartarus is burrowing!", "Tartarus đang chui xuống đất!"),
            ["toast.cracking"] = ("The ground is cracking: get clear!", "Mặt đất đang nứt: tránh ra ngay!"),
            ["toast.landing"] = ("Enemy troops landing: {count|# vehicle|# vehicles}", "Địch đổ bộ: {count} xe"),
            ["part.engine"] = ("engine", "động cơ"),
            ["part.hangar"] = ("drone bay", "nhà chứa drone"),
