            // Prompt 19: the orbital boss's parts (Silver Bug).
            ["part.mainengine"] = ("main engine", "động cơ đẩy chính"),
            ["part.thruster"] = ("manoeuvring thruster", "động cơ điều hướng"),
            ["part.pdlaser"] = ("point-defence laser", "tháp la-de phòng thủ điểm"),
            ["part.podbay"] = ("drop-pod bay", "cửa thả khoang đổ bộ"),
            ["part.uplink"] = ("satellite uplink", "ăng-ten liên kết vệ tinh"),
            ["radio.part.maingun"] = ("Command: {boss}'s main gun is down. It is fighting with what it has left: press it!", "Chỉ huy: pháo chính của {boss} đã bị phá. Nó chỉ còn chút hỏa lực: dồn lên!"),
            ["radio.part.shield"] = ("Command: {boss}'s shield generator is gone. No more shields: hit it with everything.", "Chỉ huy: máy phát khiên của {boss} đã tan. Hết khiên rồi: dồn toàn bộ hỏa lực vào nó."),
            ["radio.part.bay"] = ("Command: a drone bay on {boss} is wrecked. Fewer drones in the air from now on.", "Chỉ huy: một cửa thả drone của {boss} đã bị phá. Từ giờ ít drone hơn."),
            ["radio.part.locomotive"] = ("Command: {boss}'s locomotive is hit! It is crawling at half speed: catch it.", "Chỉ huy: đầu máy của {boss} trúng đòn! Nó chỉ còn bò nửa tốc độ: đuổi theo."),
            ["radio.part.drill"] = ("Command: {boss}'s drill head is shattered. It cannot dig under any more!", "Chỉ huy: mũi khoan của {boss} đã vỡ. Nó không chui xuống đất được nữa!"),
            ["radio.part.ramp"] = ("Command: {boss}'s landing ramp is wrecked. No more troops come ashore from it.", "Chỉ huy: cửa đổ bộ của {boss} đã hỏng. Không còn quân nào đổ bộ từ nó nữa."),
            ["radio.part.antenna"] = ("Command: {boss}'s command antenna is down. Its army has lost its edge!", "Chỉ huy: ăng-ten chỉ huy của {boss} đã đổ. Quân của nó mất lợi thế rồi!"),
            ["radio.part.mainengine"] = ("Command: {boss}'s main engine is wrecked: it stays low until it falls!", "Chỉ huy: động cơ chính của {boss} đã bị phá: nó ở tầng thấp tới khi rơi!"),
            ["radio.part.uplink"] = ("Command: {boss}'s satellite uplink is down. No more rods falling from orbit!", "Chỉ huy: ăng-ten vệ tinh của {boss} đã bị phá. Hết thanh vonfram rơi từ quỹ đạo!"),
            ["radio.part.podbay"] = ("Command: {boss}'s drop-pod bay is wrecked. No more pods coming down!", "Chỉ huy: cửa thả khoang đổ bộ của {boss} đã bị phá. Hết khoang đổ bộ rơi xuống!"),
            ["toast.partRepaired"] = ("{card} patched its {part} back together", "{card} đã tự vá lại {part}"),
            ["toast.partFocus"] = ("Every unit in range: target the {part}", "Toàn quân trong tầm: ưu tiên bắn {part}"),
            ["toast.partFocusOff"] = ("Part order cancelled", "Đã hủy lệnh ưu tiên bộ phận"),
            ["boss.partHint"] = ("Tap a part to focus fire on it", "Chạm vào bộ phận để dồn hỏa lực"),
            ["guide.parts"] = ("Parts", "Bộ phận"),
            ["guide.parts.rule"] = ("Break a part and its weapon or skill stops for the rest of the battle, and the body loses 30% of the part's health. Only direct hits damage a part: blasts, fire and strikes land on the body. Tap a part on the boss, or its icon under the boss bar, and every unit in range targets it until it breaks.", "Phá một bộ phận thì vũ khí hoặc kỹ năng của nó ngừng tới hết trận, và thân mất thêm 30% máu của bộ phận đó. Chỉ phát trúng trực tiếp mới làm hại bộ phận: nổ lan, lửa và hỏa lực yểm trợ chỉ trúng thân. Chạm vào bộ phận trên boss, hoặc vào biểu tượng dưới thanh máu boss, là toàn quân trong tầm dồn bắn nó tới khi vỡ."),
            ["guide.parts.patch"] = ("Once a battle it patches one broken part back to half health: the one with its heaviest gun.", "Mỗi trận một lần, nó tự vá một bộ phận đã vỡ về nửa máu: bộ phận có vũ khí mạnh nhất."),
            ["guide.parts.lock"] = ("Its hull takes no damage until two of its {seconds}s are down.", "Thân nó không nhận sát thương cho tới khi phá được hai {seconds}."),
            ["guide.part.line"] = ("{part}: {effect}", "{part}: {effect}"),
            ["guide.parts.tip.armored_train"] = ("Tip: break the [[locomotive]] first to halve its speed, then its gun cars. It patches one broken part once, the heavier gun first, so finish that car twice.", "Mẹo: phá [[đầu máy]] trước để nó chậm một nửa, rồi tới các toa pháo. Nó tự vá một bộ phận một lần, ưu tiên pháo nặng, nên hãy phá toa đó lần nữa."),
            ["guide.parts.tip.nuke_train"] = ("Tip: the [[locomotive]] is the part that matters: break it and the train crawls at half speed while you work on the missile car.", "Mẹo: [[đầu máy]] là bộ phận quan trọng nhất: phá nó là tàu chỉ bò nửa tốc độ trong khi bạn đánh toa tên lửa."),
            ["guide.parts.tip.behemoth"] = ("Tip: have your tanks tap the [[main gun]]: without its twin barrels it is a slow box of flak and missiles. Its [[protection system]] shoots down two anti-tank missiles at a time: break it, or send guns. Anti-air should take its flak first if your aircraft are near.", "Mẹo: cho xe tăng dồn bắn [[pháo chính]]: mất cặp nòng đó nó chỉ còn là khối thép chậm chạp với cao xạ và tên lửa. [[Hệ thống bảo vệ chủ động]] bắn hạ hai tên lửa chống tăng mỗi lượt: phá nó, hoặc dùng pháo. Phòng không nên phá cao xạ trước nếu máy bay ta ở gần."),
            ["guide.parts.tip.behemoth_tempest"] = ("Tip: break the [[shield generator]] before its health gets low, or its shields will soak your burst; its [[laser emitter]] shoots down missiles, drones and rockets, so use guns, shells or smoke on it until that is gone.", "Mẹo: phá [[máy phát khiên]] trước khi nó xuống máu, không thì khiên sẽ nuốt đợt dồn hỏa lực của bạn; [[bộ phát la-de]] bắn hạ tên lửa, drone và rốc-két, nên hãy dùng pháo, đạn hoặc khói cho tới khi phá được nó."),
            ["guide.parts.tip.behemoth_inferno"] = ("Tip: each [[flamethrower]] broken halves its fire; break both and it can only lob thermobaric rockets. Stay out of 20 m meanwhile, and off the burning trail behind it: its [[fuel tanks]] feed that.", "Mẹo: mỗi [[súng phun lửa]] bị phá là lửa giảm một nửa; phá cả hai thì nó chỉ còn bắn rốc-két nhiệt áp. Trong lúc đó hãy giữ ngoài 20 m và tránh vệt lửa phía sau nó: [[thùng nhiên liệu]] nuôi vệt lửa đó."),
            ["guide.parts.tip.fortress_hive"] = ("Tip: the two [[drone launchers]] feed its swarms: break both and the launches stop. Its [[jamming mast]] throws guided missiles wide within 30 m: break it with guns before you trust missiles. Its EMP emitter is worth breaking before a close assault.", "Mẹo: hai [[giàn phóng drone]] nuôi bầy drone của nó: phá cả hai là hết phóng. [[Cột gây nhiễu]] làm tên lửa dẫn đường trong 30 m bay lệch: phá nó bằng pháo trước khi trông vào tên lửa. Nên phá bộ phát EMP trước khi áp sát."),
            ["guide.parts.tip.mobile_fortress"] = ("Tip: break the [[howitzer]] to end its barrages, and the EMP emitter before your armour closes in.", "Mẹo: phá [[lựu pháo]] để chấm dứt các loạt pháo dồn, và phá bộ phát EMP trước khi thiết giáp ta áp sát."),
            ["guide.parts.tip.fortress_bastion"] = ("Tip: each [[autocannon turret]] covers one quarter: break the turrets on one side and attack from there. Its patch brings the mortar back first.", "Mẹo: mỗi [[tháp pháo tự động]] chỉ phủ một góc: phá các tháp ở một phía rồi đánh từ phía đó. Khi tự vá nó ưu tiên khẩu cối."),
            ["guide.parts.tip.silver_bug"] = ("Tip: break the [[main engine]] to trap it at low altitude, and the [[satellite uplink]] to stop the tungsten rods; its two [[point-defence lasers]] are worth clearing before you trust missiles.", "Mẹo: phá [[động cơ đẩy chính]] để nhốt nó ở tầng thấp, và phá [[ăng-ten liên kết vệ tinh]] để chặn thanh vonfram; nên dọn hai [[tháp la-de phòng thủ điểm]] trước khi trông vào tên lửa."),
            ["guide.parts.tip.sky_fortress"] = ("Tip: each [[engine]] broken slows its orbit by 15%: slower passes mean more time for your anti-air. Its 105 mm is the gun that kills tanks.", "Mẹo: mỗi [[động cơ]] bị phá làm vòng bay chậm 15%: bay chậm hơn là phòng không ta có thêm thời gian. Khẩu 105 mm là thứ giết xe tăng."),
            ["guide.parts.tip.mega_gunship"] = ("Tip: break the [[rear rotor]] and it turns half as fast and loses its aim; its rocket pods and chin guns are the parts hurting your ground units.", "Mẹo: phá [[cánh quạt sau]] là nó xoay chậm một nửa và khó ngắm; hộp rốc-két và pháo dưới mũi là thứ làm hại quân mặt đất."),
            ["guide.parts.tip.drone_mothership"] = ("Tip: break the [[drone bay]] and the [[UAV launch bay]] to stop its drones, and the [[shield generator]] before its health drops.", "Mẹo: phá [[cửa thả drone]] và [[khoang phóng UAV]] để chặn drone, và phá [[máy phát khiên]] trước khi nó xuống máu."),
            ["guide.parts.tip.rail_supergun"] = ("Tip: break the [[fire control]] and its shells fall wide; each [[rail tractor]] broken slows its fire; break the [[main gun]] and it fires no more.", "Mẹo: phá [[trạm chỉ thị mục tiêu]] là đạn rơi lệch; mỗi [[đầu máy kéo]] bị phá làm nó bắn thưa hơn; phá [[pháo chính]] là nó hết bắn."),
            ["guide.parts.tip.earth_borer"] = ("Tip: hit the [[drill head]] in the seconds after it breaks out: once it is shattered it can never go under again.", "Mẹo: đánh vào [[mũi khoan]] trong vài giây ngay sau khi nó trồi lên: vỡ rồi là nó không bao giờ chui xuống đất được nữa."),
            ["guide.parts.tip.command_airship"] = ("Tip: two [[engines]] open its hull; then its drone bays and the radar that aims its flak.", "Mẹo: phá hai [[động cơ]] để mở thân; sau đó tới các nhà chứa drone và radar ngắm cao xạ."),
            ["guide.parts.tip.landing_hovercraft"] = ("Tip: break the [[landing ramp]] and it lands no more troops; each [[thrust fan]] broken slows it by 30%. Its two [[close-in weapons]] shoot down missiles and rockets: break them before a missile attack.", "Mẹo: phá [[cửa đổ bộ]] là nó hết đổ quân; mỗi [[quạt đẩy]] bị phá làm nó chậm 30%. Hai [[pháo phòng thủ tầm gần]] bắn hạ tên lửa và rốc-két: phá chúng trước khi tấn công bằng tên lửa."),
            ["guide.parts.tip.leviathan"] = ("Tip: take the [[lighthouse]] to see the fleet; break both [[CIWS]] (or sink the cruiser and corvette beside it) before you send missiles and drones; each broken [[main gun]] takes a third off its salvos and its broadside; the [[radar]] spreads its shells; the [[engine room]] slows its run.", "Mẹo: chiếm [[hải đăng]] để thấy hạm đội; phá cả hai [[CIWS]] (hoặc đánh chìm tuần dương hạm và tàu hộ vệ bên cạnh) trước khi dùng tên lửa và drone; mỗi [[pháo chính]] bị phá bớt một phần ba loạt pháo và loạt bắn mạn; phá [[radar]] thì đạn pháo rơi lệch; phá [[buồng máy]] thì nó chạy chậm lại."),
            ["guide.parts.tip.supreme_command"] = ("Tip: break the [[command antenna]] first: its army loses the command aura at once.", "Mẹo: phá [[ăng-ten chỉ huy]] trước tiên: quân của nó mất ngay hào quang chỉ huy."),
            ["part.fx.guns"] = ("its guns fall silent", "vũ khí của nó im tiếng"),
            ["part.fx.skill.Shield"] = ("no more shields", "hết khiên"),
            ["part.fx.skill.Summon"] = ("no more drones or escorts from it", "không còn thả drone hay gọi hộ tống"),
            ["part.fx.skill.Emp"] = ("no more EMP bursts", "hết đòn EMP"),
            ["part.fx.skill.Barrage"] = ("no more rapid barrages", "hết loạt bắn dồn dập"),
            ["part.fx.skill.Other"] = ("its special ability stops", "kỹ năng đặc biệt ngừng"),
            ["part.fx.stop.bombard"] = ("the super-gun fires no more", "siêu pháo ngừng bắn"),
            ["part.fx.stop.spotter"] = ("its shells fall wide of the mark", "đạn của nó rơi lệch xa mục tiêu"),
            ["part.fx.stop.burrow"] = ("it can no longer dig under", "nó không chui xuống đất được nữa"),
            ["part.fx.stop.landing"] = ("it lands no more troops", "nó không đổ quân được nữa"),
            ["part.fx.stop.aura"] = ("its army loses the command aura", "quân của nó mất hào quang chỉ huy"),
            ["part.fx.stop.aps"] = ("fewer of your missiles, drones and rockets are shot down (none once every one is broken)", "ít tên lửa, drone và rốc-két của ta bị bắn hạ hơn (không còn khi phá hết)"),
            ["part.fx.stop.jammer"] = ("your guided missiles fly true near it again", "tên lửa dẫn đường của ta lại bắn trúng khi ở gần nó"),
            ["part.fx.stop.cruise"] = ("it fires no more cruise missiles", "nó không phóng tên lửa hành trình được nữa"),
            ["part.fx.stop.craft"] = ("it sends no more landing craft", "nó không thả tàu đổ bộ được nữa"),
            ["part.fx.stop.radar"] = ("its salvos and missiles fall wide and its CIWS misses now and then", "loạt pháo và tên lửa của nó rơi lệch, CIWS thỉnh thoảng bắn trượt"),
            ["part.fx.stop.trail"] = ("it leaves no more fire behind it", "nó không còn để lại vệt lửa phía sau"),
            ["part.fx.stop.thrust"] = ("it can no longer climb to high altitude: it stays low until it crashes", "nó không lên lại tầng cao được nữa: giữ ở tầng thấp cho tới khi rơi"),
            ["part.fx.stop.pods"] = ("it drops no more pods", "nó không thả khoang đổ bộ được nữa"),
            ["part.fx.speed"] = ("{percent}% slower", "chậm hơn {percent}%"),
            ["part.fx.turn"] = ("turns {percent}% slower and tracks targets badly", "xoay chậm hơn {percent}%, khó bám mục tiêu"),
            ["part.fx.cadence"] = ("fires {percent}% less often", "bắn thưa hơn {percent}%"),
            ["part.fx.spread"] = ("its guns scatter wide", "vũ khí của nó bắn tản mát"),
            ["part.fx.none"] = ("weakens the body", "làm thân yếu đi"),
