            ["mission.m01.name"] = ("Landfall", "Đổ bộ"),
            ["mission.m01.brief"] = ("Take the town and both depots from a weak garrison.", "Chiếm thị trấn và hai kho nhiên liệu từ đồn địch yếu."),
            ["mission.m02.name"] = ("Supply Run", "Đoàn xe tải tiếp tế"),
            ["mission.m02.brief"] = ("Get at least two supply trucks to the east depot.", "Đưa ít nhất hai xe tải tiếp tế tới kho phía đông."),
            ["mission.m03.name"] = ("Harpy", "Harpy"),
            ["mission.m03.brief"] = ("A giant gunship rules the sky over Ashfield. Bring it down.", "Một trực thăng khổng lồ làm chủ bầu trời Ashfield. Bắn hạ nó."),
            ["mission.m04.name"] = ("Oil and Sand", "Dầu và cát"),
            ["mission.m04.brief"] = ("Hold out at the oil field for five minutes.", "Trụ vững ở mỏ dầu trong năm phút."),
            ["mission.m05.name"] = ("Refinery Inferno", "Hỏa ngục lọc dầu"),
            ["mission.m05.brief"] = ("Blow up every tower and storage tank of the refinery.", "Cho nổ tung mọi tháp và bồn chứa của nhà máy lọc dầu."),
            ["mission.m06.name"] = ("Behemoth", "Quái vật thép"),
            ["mission.m06.brief"] = ("A land battleship crawls out of the sandstorm. Destroy it.", "Một chiến hạm mặt đất bò ra từ bão cát. Tiêu diệt nó."),
            ["mission.m07.name"] = ("Blind the Radar", "Làm mù radar"),
            ["mission.m07.brief"] = ("Destroy the radar station on the western heights.", "Phá hủy trạm radar trên cao điểm phía tây."),
            ["mission.m08.name"] = ("Village in the Fog", "Ngôi làng trong sương"),
            ["mission.m08.brief"] = ("Hold the village for five minutes against everything they send.", "Giữ ngôi làng năm phút trước mọi đợt tấn công."),
            ["mission.m09.name"] = ("Jötunn", "Jötunn"),
            ["mission.m09.brief"] = ("A mobile fortress is grinding down the valley. Stop it.", "Một pháo đài di động đang nghiền nát thung lũng. Chặn nó lại."),
            ["mission.m10.name"] = ("Storm the Port", "Tấn công cảng"),
            ["mission.m10.brief"] = ("The enemy holds the whole port. Take all three objectives.", "Địch giữ toàn bộ cảng. Chiếm cả ba cứ điểm."),
            ["mission.m11.name"] = ("Dockside Convoy", "Đoàn xe bến cảng"),
            ["mission.m11.brief"] = ("Bring three of five trucks through the port to the docks.", "Đưa ba trong năm xe tải qua cảng tới bến."),
            ["mission.m12.name"] = ("Juggernaut", "Juggernaut"),
            ["mission.m12.brief"] = ("An armoured train is heading for the docks. Destroy it before it arrives.", "Một đoàn tàu bọc thép đang lao về bến cảng. Phá hủy nó trước khi tới nơi."),
            ["mission.m00.name"] = ("Boot Camp", "Huấn luyện"),
            ["mission.m00.brief"] = ("Learn the ropes: take the crossroads village from a handful of scouts.", "Làm quen: chiếm làng ngã tư từ tay vài xe trinh sát."),
            ["mission.m13.name"] = ("Molten Gate", "Cổng Dung Nham"),
            ["mission.m13.brief"] = ("A fortress guards the geothermal plant. Break through the walls at night and level the command HQ.", "Pháo đài canh giữ nhà máy địa nhiệt. Phá tường trong đêm và san phẳng sở chỉ huy."),
            ["mission.m14.name"] = ("Temple of Ash", "Đền Tro"),
            ["mission.m14.brief"] = ("Elite columns hold the temple ford and the east village. Take the whole pass.", "Các đoàn tinh nhuệ giữ bến đền cổ và làng phía đông. Chiếm trọn con đèo."),
            ["mission.m15.name"] = ("Hive over Skyhold", "Hive trên Skyhold"),
            ["mission.m15.brief"] = ("The Matriarch is launching drone swarms from over the airbase. Bring it down.", "Matriarch đang phóng bầy drone trên căn cứ không quân. Hạ nó xuống."),
            ["mission.m16.name"] = ("Nemesis Line", "Tuyến Nemesis"),
            ["mission.m17.name"] = ("Scorpion Hunt", "Săn Bọ Cạp"),
            ["mission.m17.brief"] = ("Three rocket and missile batteries are hiding among the Red Rock mesas. Find them, marked in red, and knock them out.", "Ba dàn pháo phản lực và tên lửa đang ẩn giữa các khối đá ở Red Rock. Tìm chúng (đánh dấu đỏ) và tiêu diệt."),
            ["mission.m18.name"] = ("Behemoth Mk.II", "Behemoth Mk.II"),
            ["mission.m18.brief"] = ("The Behemoth is back, rebuilt and heavier, pushing through the snow of Whiteout Pass. Stop it for good.", "Behemoth quay lại, được đóng lại nặng hơn, đang tiến qua tuyết Whiteout Pass. Chặn đứng nó vĩnh viễn."),
            ["mission.m19.name"] = ("Eyes on the Yard", "Mắt Nhìn Bãi Sắt"),
            ["mission.m19.brief"] = ("Fog over the Rust Yard. Get a vehicle onto each of the three objectives and look before the enemy digs in.", "Sương mù phủ Rust Yard. Đưa phương tiện đến từng cứ điểm trong ba cứ điểm để trinh sát trước khi địch cố thủ."),
            ["mission.m20.name"] = ("Air Raid", "Không Kích"),
            ["mission.m20.brief"] = ("Wave after wave of enemy aircraft is coming for Skyhold. Bring down sixteen of them.", "Từng đợt máy bay địch lao tới Skyhold. Bắn hạ mười sáu chiếc."),
            ["mission.m21.name"] = ("Silver Sky", "Bầu Trời Bạc"),
            ["mission.m21.brief"] = ("Aurel's orbital spacecraft, Project Icarus, is dropping out of orbit over Dune Break to strike from the sky. Bring it down.", "Phi thuyền quỹ đạo của Aurel, dự án Icarus, đang hạ khỏi quỹ đạo trên Dunebreak để tấn công từ trên không. Hạ nó xuống."),
            ["mission.m22.name"] = ("Harvest Guard", "Giữ Mùa Gặt"),
            ["mission.m22.brief"] = ("The enemy wants the silos and the water tower at the south end of Greenvale. Keep at least one standing for eight minutes.", "Địch muốn phá các kho và tháp nước ở phía nam Greenvale. Giữ ít nhất một công trình đứng vững trong tám phút."),
            ["mission.m16.brief"] = ("A missile train is crossing Metro City to its launch site. Stop it before the countdown ends.", "Đoàn tàu tên lửa đang băng qua Metro City tới bãi phóng. Chặn nó trước khi đếm ngược kết thúc."),
            ["tip.auto"] = ("Your army fights on its own. You set the plan: where to fight, what to buy, when to strike.", "Quân ta tự chiến đấu. Bạn vạch kế hoạch: đánh ở đâu, mua gì, khi nào yểm trợ."),
            ["tip.deploy"] = ("Tap a vehicle card at the bottom to buy it with CP. It drives in from your base.", "Chạm thẻ xe ở dưới để mua bằng CP. Xe sẽ chạy ra từ căn cứ."),
            ["tip.points"] = ("Tap A, B or C at the top to send the whole army to that objective.", "Chạm A, B hoặc C ở trên để dồn cả đội quân tới cứ điểm đó."),
            ["tip.strike"] = ("Support cards call fire support: tap one, then tap the map where it should land.", "Thẻ yểm trợ gọi hỏa lực: chạm thẻ, rồi chạm vào bản đồ nơi muốn đánh."),
            ["tip.select"] = ("Tap a vehicle to take it over by hand; tap the ground to send it there.", "Chạm vào một xe để tự điều khiển; chạm mặt đất để gửi nó tới đó."),
            ["tip.counters"] = ("Every unit beats some and loses to others: the panel shows who.", "Mỗi đơn vị khắc chế một số loại và bị loại khác khắc chế: bảng chọn cho biết."),
            ["tip.items"] = ("Coins buy skins, premium vehicles and items like the MOAB in the shop.", "Xu dùng để mua ngụy trang, xe cao cấp và vật phẩm như bom MOAB trong cửa hàng."),
            ["unit.supply_truck"] = ("Supply truck", "Xe tải tiếp tế"),
