            ["short.fortress_bastion"] = ("Bastion", "Bastion"),
            ["short.sky_fortress"] = ("Spectre", "Spectre"),
            ["note.rail_supergun"] = ("Kessler's 80 cm railway gun on its own bed at the edge of the field: one shell every 25 s at your biggest group anywhere on the map, marked 3 s ahead, behind walls, guns and a fire-control post.", "Pháo đường ray 80 cm của Kessler trên nền ray riêng ở mép chiến trường: cứ 25 giây một quả đạn vào cụm quân đông nhất của bạn ở bất cứ đâu, có cảnh báo trước 3 giây, sau tường, súng và trạm chỉ thị mục tiêu."),
            ["note.earth_borer"] = ("Varga's boring machine: it dives, bores unseen under your biggest group of ground vehicles and breaks out in a quake that stuns everything within 15 m. The cracks give 2 s warning.", "Máy khoan của Varga: chui xuống đất, khoan ngầm tới dưới cụm xe mặt đất đông nhất của bạn rồi trồi lên gây rung chấn làm choáng mọi thứ trong 15 m. Mặt đất nứt báo trước 2 giây."),
            ["note.command_airship"] = ("Wolff's flying battleship: four engines, two drone bays and a fire-control radar, each with its own health; the hull takes no damage until two engines are down.", "Chiến hạm bay của Wolff: bốn động cơ, hai nhà chứa drone và một radar điều khiển hỏa lực, mỗi bộ phận có máu riêng; thân chỉ nhận sát thương khi đã phá hai động cơ."),
            ["note.landing_hovercraft"] = ("An air-cushion landing craft on a fixed run: every 35 s it drops its ramp and lands 3 or 4 vehicles. Stop it before it has landed them all.", "Tàu đệm khí đổ bộ chạy theo lộ trình cố định: cứ 35 giây hạ cửa đổ bộ và thả 3–4 xe lên bờ. Phải chặn nó trước khi đổ bộ hết."),
            ["note.leviathan"] = ("Kessler's battleship at sea: three triple 460 mm turrets shell the shore, two triple 155 mm and eight 25 mm mounts, cruise missiles at the base, CIWS against missiles and drones. Sides armour 4, deck 2.", "Thiết giáp hạm của Kessler trên biển: ba tháp pháo ba nòng 460 mm nã vào bờ, hai tháp ba nòng 155 mm và tám bệ 25 mm, tên lửa hành trình đánh vào căn cứ, CIWS chặn tên lửa và drone. Giáp hông cấp 4, boong cấp 2."),
            ["note.sea_corvette"] = ("An escort: a 76 mm gun on the shore and a CIWS that also covers Leviathan within 32 m.", "Tàu hộ vệ: pháo 76 mm bắn vào bờ và CIWS che luôn cả Leviathan trong vòng 32 m."),
            ["note.sea_cruiser"] = ("An escort: two twin 203 mm turrets on the shore and two CIWS that also cover Leviathan within 30 m.", "Tàu hộ tống: hai tháp pháo nòng đôi 203 mm bắn vào bờ và hai CIWS che luôn cả Leviathan trong vòng 30 m."),
            ["note.missile_boat"] = ("Fast and thin-skinned: it dashes in to the pier heads, fires its rockets and runs back out.", "Nhanh và giáp mỏng: lao vào sát đầu cầu tàu, bắn rốc-két rồi quay ra."),
            ["note.landing_craft"] = ("Runs two tanks up the beach and goes back for more.", "Chở hai xe tăng lên bãi biển rồi quay về lấy thêm."),
            ["note.coastal_battery"] = ("An abandoned coastal battery: hold it with ground vehicles to take it; its twin 155 mm fire on ships out to the far lane.", "Trận địa pháo bờ biển bỏ hoang: đứng giữ bằng xe mặt đất để chiếm; hai khẩu 155 mm bắn vào tàu tới tận tuyến xa."),
            ["note.supreme_command"] = ("General {@lyhan}'s armoured headquarters after his betrayal: two light guns and nothing else, but every enemy within 40 m hits 20% harder and fires 20% faster.", "Sở chỉ huy bọc thép của Tướng {@lyhan} sau khi phản bội: chỉ có hai súng máy nhẹ, nhưng mọi quân địch trong 40 m tăng 20% sát thương và 20% tốc độ bắn."),
            ["note.behemoth_inferno"] = ("A Behemoth with twin flame projectors and a thermobaric rocket box: burns everything near it and sets the ground on fire. Keep your distance; it has only one flak gun against aircraft.",
                "Behemoth mang hai súng phun lửa lớn và hộp rốc-két nhiệt áp: thiêu mọi thứ ở gần và đốt cháy mặt đất. Hãy giữ khoảng cách; nó chỉ có một khẩu pháo phòng không."),
            ["note.behemoth_tempest"] = ("A Behemoth built round a railgun: it charges for a second (watch the coils glow) and pierces everything in a line from far off. Two coilguns, a shield. Spread out and close in.",
                "Behemoth xây quanh một khẩu pháo điện từ: nạp năng lượng một giây (các cuộn dây phát sáng) rồi xuyên thủng cả hàng từ rất xa. Hai pháo điện từ, có khiên. Hãy dàn quân và áp sát."),
            ["note.fortress_hive"] = ("A mobile fortress with no big gun: swarms of drones from two racks, a SAM battery and flak. Deadly to aircraft; tanks and artillery break it.",
                "Pháo đài di động không có pháo lớn: bầy drone từ hai giàn phóng, dàn tên lửa phòng không và pháo cao xạ. Cực nguy hiểm với máy bay; xe tăng và pháo binh mới hạ được."),
            ["note.fortress_bastion"] = ("The toughest boss on the field: four autocannon turrets, a heavy mortar, and it patches itself up. Bring tank hunters and heavy guns.",
                "Boss lì đòn nhất: bốn tháp pháo tự động, một khẩu cối hạng nặng, và tự vá giáp. Cần xe diệt tăng và pháo hạng nặng."),
            ["note.sky_fortress"] = ("A boss AC-130: circles high over its prey with a 105 mm, two 40 mm and a 25 mm down its left side, Griffin missiles from the ramp. Only anti-aircraft and fighters reach it.",
                "AC-130 cỡ boss: bay vòng trên cao quanh mục tiêu với pháo 105 mm, hai 40 mm và một 25 mm bên trái, tên lửa Griffin từ cửa sau. Chỉ phòng không và tiêm kích với tới."),
            // Rewards and ads.
            ["result.double"] = ("Double coins", "Nhân đôi xu"),
            ["result.doubleSub"] = ("Watch a short ad", "Xem một quảng cáo ngắn"),
            ["result.next"] = ("Next mission", "Nhiệm vụ tiếp"),
            ["result.unlocked"] = ("Unlocked: {name}", "Đã mở khóa: {name}"),
            ["ad.title"] = ("ADVERTISEMENT", "QUẢNG CÁO"),
            ["ad.body"] = ("Test ad: a real ad network is connected before release.", "Quảng cáo thử nghiệm: mạng quảng cáo thật sẽ được gắn trước khi phát hành."),
            ["ad.claim"] = ("Claim double coins", "Nhận gấp đôi xu"),
            ["ad.close"] = ("Close", "Đóng"),
            // Prompt 17 C: the new units and towers.
            ["unit.stealth_fighter"] = ("Stealth fighter", "Tiêm kích tàng hình"),
            ["unit.wingman_drone"] = ("Wingman drone", "Drone hộ vệ"),
            ["unit.laser_tank"] = ("Laser tank destroyer", "Xe la-de diệt tăng"),
            ["unit.shield_carrier"] = ("Shield carrier", "Xe phát khiên"),
            ["unit.bunker_vehicle"] = ("Deployable bunker", "Xe công sự triển khai"),
            ["unit.swarm_carrier"] = ("Drone mothership aircraft", "Máy bay mẹ thả drone"),
            ["unit.shield_tower"] = ("Shield generator", "Máy phát khiên"),
            ["unit.cp_relay"] = ("CP relay", "Trạm tiếp tế CP"),
            ["short.stealth_fighter"] = ("Stealth fighter", "TK tàng hình"),
            ["short.wingman_drone"] = ("Wingman", "Drone hộ vệ"),
            ["short.laser_tank"] = ("Laser tank", "La-de diệt tăng"),
            ["short.shield_carrier"] = ("Shield carrier", "Phát khiên"),
            ["short.bunker_vehicle"] = ("Bunker", "Công sự"),
            ["short.swarm_carrier"] = ("Mothership", "Máy bay mẹ"),
            ["short.shield_tower"] = ("Shield gen.", "Máy phát khiên"),
            ["short.cp_relay"] = ("CP relay", "Trạm CP"),
            ["branch.shield_tower.bulwark"] = ("Shield dome", "Vòm khiên"),
            ["branch.shield_tower.bulwark.info"] = ("One big, stronger dome over the whole area.", "Một vòm lớn, chắc hơn, che cả khu vực."),
            ["branch.cp_relay.hardened"] = ("CP relay", "Trạm tiếp tế"),
            ["branch.cp_relay.hardened.info"] = ("Steady CP, tougher and better armoured; pays nothing for a few seconds after a hit.", "Thêm CP đều đặn, chắc và giáp dày hơn; bị bắn thì ngừng trả vài giây."),
            ["note.stealth_fighter"] = ("A fifth-generation fighter: enemies see it only close up, or just after it fires. Missiles for aircraft, two small guided bombs for air defences, a 25 mm gun.", "Tiêm kích thế hệ năm: địch chỉ thấy khi nó ở rất gần hoặc vừa khai hỏa. Tên lửa đánh máy bay, hai bom dẫn đường nhỏ diệt phòng không, pháo 25 mm."),
            ["note.wingman_drone"] = ("A loyal wingman: it flies on the wing of the nearest manned aircraft of its side and may draw the anti-air missiles fired at it. Outside the six-aircraft cap, four a side.", "Drone hộ vệ: bay kèm máy bay có người lái gần nhất của phe ta và có thể hút tên lửa phòng không bắn vào máy bay đó. Không tính vào trần sáu máy bay, tối đa bốn chiếc."),
            ["note.laser_tank"] = ("A focused-laser tank destroyer: the beam burns harder the longer it stays on one target, from about a third of its power to double in six seconds. Missile defences cannot stop it; smoke can.", "Xe diệt tăng la-de tập trung: tia càng giữ lâu trên một mục tiêu càng đốt mạnh, từ khoảng một phần ba lên gấp đôi trong sáu giây. Hệ thống đánh chặn không chặn được; màn khói thì chặn được."),
            ["note.shield_carrier"] = ("A mobile shield carrier: its dome takes every hit but energy for the friends inside until it breaks, and is back 20 s after the last hit. Domes do not add up.", "Xe phát khiên di động: vòm khiên hấp thụ mọi đòn trừ năng lượng cho đồng minh bên trong cho tới khi vỡ, hồi lại 20 giây sau đòn cuối. Nhiều vòm không cộng dồn."),
            ["note.bunker_vehicle"] = ("A deployable bunker: standing still it digs in for 3 s: front armour two levels thicker, 30% more reach, turret all round. It packs up in 3 s to move.", "Xe công sự triển khai: đứng yên thì mất 3 giây để thành ụ cố định: giáp trước dày thêm hai cấp, tầm bắn xa thêm 30%, tháp pháo xoay 360°. Thu lại cũng mất 3 giây."),
            ["note.swarm_carrier"] = ("A drone mothership: a big, slow aircraft that flies a swarm of FPV drones out to anywhere and releases them one after another over the target, each finding its own, and drops two guided bombs from the same bay. The drones are not aircraft.", "Máy bay mẹ thả drone: máy bay to, chậm, chở bầy drone FPV tới bất cứ đâu rồi thả lần lượt xuống vùng mục tiêu, mỗi chiếc tự tìm mục tiêu, và thả thêm hai bom dẫn đường từ cùng khoang. Drone không tính là máy bay."),
            ["note.shield_tower"] = ("A shield generator: its dome takes every hit but energy for the towers and units of its side inside until it breaks, and is back 30 s after its last hit.", "Máy phát khiên: vòm khiên hấp thụ mọi đòn trừ năng lượng cho tháp và quân phe mình bên trong cho tới khi vỡ, hồi lại 30 giây sau đòn cuối."),
            ["note.cp_relay"] = ("A CP relay: its side earns more CP (a second relay less, never more than two). It pays nothing for a few seconds after it is hit, and cannot go on an outpost.", "Trạm tiếp tế CP: phe sở hữu kiếm thêm CP (trạm thứ hai ít hơn, tối đa hai trạm). Bị bắn thì ngừng trả vài giây, và không đặt được ở tiền đồn."),

            // Prompt 25 F2 batch A (DECISIONS 25F2-A): the balance sheet's new units and structures ("Đề xuất thêm", "Công trình
            // mới"): names, short names (15 letters at most) and reference lines with the real model; their Guide cards are in GuideText.
            ["target.paradrop"] = ("Tap ground your side can see to drop {unit} (tap the card again to send it to the drop zone)",
                "Chạm vào vùng phe ta nhìn thấy để thả dù {unit} (chạm thẻ lần nữa để đưa về bãi thả)"),
            ["err.DropNotSeen"] = ("Drop only where your side can see, and never into an enemy base", "Chỉ thả dù nơi phe ta nhìn thấy, không thả vào căn cứ địch"),
            // dx01: Tháp cao xạ hạng nặng Flak 88.
            ["unit.heavy_flak_tower"] = ("Heavy flak tower", "Tháp cao xạ hạng nặng"),
            ["short.heavy_flak_tower"] = ("Heavy flak", "Cao xạ nặng"),
            ["note.heavy_flak_tower"] = ("A heavy anti-aircraft gun of the 8.8 cm Flak 36/37 class: slow, big air bursts against bombers and tight formations; lowered, it hits tanks at 50 m.", "Pháo cao xạ hạng nặng kiểu 8,8 cm Flak 36/37: bắn chậm, đạn nổ trên không bán kính lớn vào oanh tạc cơ và tốp máy bay dày; hạ nòng bắn được xe tăng ở 50 m."),
            // dx02: Xe cao xạ Bofors 40 mm.
            ["unit.aa_gun_vehicle"] = ("40 mm AA gun vehicle", "Xe cao xạ 40 mm"),
            ["short.aa_gun_vehicle"] = ("40 mm AA", "Cao xạ 40 mm"),
            ["note.aa_gun_vehicle"] = ("A tracked AA gun with a Bofors 40 mm L/70 (M42 Duster, CV90 AA): proximity-fused rounds four a second.", "Xe cao xạ bánh xích mang pháo Bofors 40 mm L/70 (M42 Duster, CV90 AA): đạn ngòi cận đích, bốn phát mỗi giây."),
            // dx03: Xe tên lửa phòng không Avenger.
            ["unit.shorad_vehicle"] = ("Light SAM vehicle", "Xe tên lửa phòng không nhẹ"),
            ["short.shorad_vehicle"] = ("Light SAM", "TL PK nhẹ"),
            ["note.shorad_vehicle"] = ("An M1097 Avenger: a light truck with a turret of eight shoulder-launched Stinger-class missiles, fired on the move.", "M1097 Avenger: xe hạng nhẹ với tháp mang tám tên lửa vác vai lớp Stinger, bắn được khi đang chạy."),
            // dx04: Xe vi sóng chống drone.
            ["unit.microwave_vehicle"] = ("Anti-drone microwave vehicle", "Xe vi sóng chống drone"),
            ["short.microwave_vehicle"] = ("Microwave", "Vi sóng"),
            ["note.microwave_vehicle"] = ("An Epirus Leonidas-type high-power microwave on an armoured truck: a pulse downs a whole swarm of drones at once.", "Hệ vi sóng công suất cao kiểu Epirus Leonidas trên xe tải bọc thép: một xung làm rơi cả bầy drone cùng lúc."),
            // dx06: Ụ pháo chống tăng.
            ["unit.at_gun_emplacement"] = ("Anti-tank gun emplacement", "Ụ pháo chống tăng"),
            ["short.at_gun_emplacement"] = ("AT gun", "Ụ chống tăng"),
            ["note.at_gun_emplacement"] = ("A towed MT-12 Rapira 100 mm anti-tank gun behind its shield and sandbags: a cheap tank killer for a small slot.", "Pháo chống tăng kéo MT-12 Rapira 100 mm sau tấm chắn và bao cát: diệt tăng rẻ tiền cho ô nhỏ."),
            // dx07: Xe tên lửa chống tăng bắn ngoài tầm nhìn.
