        /// <summary>The device's language picks the default (prompt 21 I.1): Vietnamese on a Vietnamese device, English elsewhere.</summary>
        public static bool DeviceIsVietnamese => Application.systemLanguage == SystemLanguage.Vietnamese;

        /// <summary>The language shown (MatchSettings.ApplyLanguage sets it from the settings; a paused battle relabels itself, see <see cref="Relabel"/>).</summary>
        public static bool Vietnamese { get; set; } = DeviceIsVietnamese;

        /// <summary>
        /// The language's number format (prompt 21 I.4): Vietnamese groups thousands with a dot and writes decimals
        /// with a comma (184.172; 0,75), English the other way round (184,172; 0.75). Built by hand, not from the
        /// platform's "vi-VN" data, so every player (IL2CPP, invariant globalisation) formats alike.
        /// </summary>
        public static System.Globalization.CultureInfo Culture => Vietnamese ? VietnameseCulture : System.Globalization.CultureInfo.InvariantCulture;

        private static readonly System.Globalization.CultureInfo VietnameseCulture = MakeVietnamese();

        private static System.Globalization.CultureInfo MakeVietnamese()
        {
            var c = (System.Globalization.CultureInfo)System.Globalization.CultureInfo.InvariantCulture.Clone();
            var n = c.NumberFormat;
            n.NumberGroupSeparator = n.CurrencyGroupSeparator = n.PercentGroupSeparator = ".";
            n.NumberDecimalSeparator = n.CurrencyDecimalSeparator = n.PercentDecimalSeparator = ",";
            return c;
        }

        /// <summary>A whole number in the language's format, thousands grouped (184.172 / 184,172).</summary>
        public static string Num(int value) => value.ToString("#,0", Culture);

        /// <summary>A number in the language's format ("0.#": 0,75 / 0.75).</summary>
        public static string Num(float value, string format = "0.##") => value.ToString(format, Culture);

        /// <summary>A number in the language's format.</summary>
        public static string Num(double value, string format = "0.##") => value.ToString(format, Culture);

        public static string Get(string key) =>
            Table.TryGetValue(key, out var text) || GuideText.Table.TryGetValue(key, out text) || CampaignText.Table.TryGetValue(key, out text) || UnitText.Table.TryGetValue(key, out text) ||
            BigAttackText.Table.TryGetValue(key, out text) || OrbitalText.Table.TryGetValue(key, out text) || BossText.Table.TryGetValue(key, out text) ||
            SandboxText.Table.TryGetValue(key, out text) || CommanderText.Table.TryGetValue(key, out text) || NameText.Table.TryGetValue(key, out text) || StoryText.Table.TryGetValue(key, out text) ||
            DialogueText.Table.TryGetValue(key, out text) || EventText.Table.TryGetValue(key, out text)
                // A support card's numbers come from its data (the balance pass after prompt 18, C.3); proper names come from NameText.
                ? NameText.Expand(SupportLines.Fill(key, Vietnamese ? text.vi : text.en)) : key;

        /// <summary>A text with one named placeholder ("{count} xe"): the value fills it.</summary>
        public static string Format(string key, object value) => Fill(Get(key), null, value);

        /// <summary>A text with named placeholders (prompt 21 I.3): <c>Strings.Format("camp.tooBig", ("card", name), ("size", size))</c>.</summary>
        public static string Format(string key, params (string name, object value)[] args) => Fill(Get(key), args, null);

        // {{ and }} are braces; {name}, {name:0.#} (a number format) and {name|one|other} (an English plural: "#" is the number).
        private static readonly System.Text.RegularExpressions.Regex Named =
            new(@"\{\{|\}\}|\{([A-Za-z][A-Za-z0-9_]*)(?::([^{}|]*))?(?:\|([^{}|]*)\|([^{}|]*))?\}");

        /// <summary>
        /// Fills a text's named placeholders from <paramref name="args"/> (or every one with <paramref name="single"/>).
        /// Numbers take the language's format; an unknown name stays as it is, so the screen checks catch it.
        /// </summary>
        public static string Fill(string text, (string name, object value)[] args, object single)
        {
            if (string.IsNullOrEmpty(text) || text.IndexOf('{') < 0 && text.IndexOf('}') < 0) return text;
            return Named.Replace(text, m =>
            {
                if (m.Value == "{{") return "{";
                if (m.Value == "}}") return "}";
                var name = m.Groups[1].Value;
                object value = null;
                var found = false;
                if (args == null) { value = single; found = true; }
                else
                    foreach (var (n, v) in args)
                        if (n == name) { value = v; found = true; break; }
                if (!found) return m.Value;
                var number = FormatValue(value, m.Groups[2].Success ? m.Groups[2].Value : null);
                if (!m.Groups[3].Success) return number;
                var one = IsOne(value);
                return (one ? m.Groups[3].Value : m.Groups[4].Value).Replace("#", number);
            });
        }

        private static bool IsOne(object value) => value switch
        {
            int i => i == 1 || i == -1,
            long l => l == 1 || l == -1,
            float f => Math.Abs(Math.Abs(f) - 1f) < 1e-4f,
            double d => Math.Abs(Math.Abs(d) - 1d) < 1e-6,
            string s => s == "1",
            _ => false,
        };

        private static string FormatValue(object value, string format) => value switch
        {
            null => "",
            string s => s,
            int or long or short or byte => ((IFormattable)value).ToString(format ?? "#,0", Culture),
            float or double or decimal => ((IFormattable)value).ToString(format ?? "0.##", Culture),
            IFormattable f => f.ToString(format, Culture),
            _ => value.ToString(),
        };

        /// <summary>The placeholder names of a text ({name}, {name:0.#}, {name|a|b}), for the checks.</summary>
        public static IEnumerable<string> PlaceholderNames(string text)
        {
            foreach (System.Text.RegularExpressions.Match m in Named.Matches(text ?? ""))
                if (m.Groups[1].Success) yield return m.Groups[1].Value;
        }

        public static string Error(CommandError error) => Get("err." + error);

        /// <summary>A vehicle's name; a tower's branch reads "AA tower · Flak tower".</summary>
        public static string Unit(string defId)
        {
            if (Has("unit." + defId)) return Get("unit." + defId);
            var dot = defId.IndexOf('.');
            return dot > 0 ? Get("unit." + defId.Substring(0, dot)) + " · " + Get("branch." + defId) : Get("unit." + defId);
        }

        /// <summary>A tower branch's own name ("Flak tower").</summary>
        public static string Branch(string branchId) => Get("branch." + branchId);

        /// <summary>
        /// A support's name. A boss escort's air drop ("escort_drop.&lt;unit&gt;", prompt 16 F) reads "Escort drop: the
        /// unit's name", never its raw key (the balance pass after prompt 18, C.4).
        /// </summary>
        public static string Support(string defId)
        {
            const string drop = "escort_drop.";
            if (defId.StartsWith(drop, StringComparison.Ordinal) && !Table.ContainsKey("support." + defId))
                return Format("support.escort_drop", Unit(defId.Substring(drop.Length)));
            return Get("support." + defId);
        }

        /// <summary>Every entry of every text table, in the order <see cref="Get"/> reads them (the checks read them all).</summary>
        public static IEnumerable<(string key, string en, string vi, string table)> Entries
        {
            get
            {
                var tables = new (string name, IReadOnlyDictionary<string, (string en, string vi)> table)[]
                {
                    ("Strings", Table), ("GuideText", GuideText.Table), ("CampaignText", CampaignText.Table), ("UnitText", UnitText.Table),
                    ("BigAttackText", BigAttackText.Table), ("OrbitalText", OrbitalText.Table), ("BossText", BossText.Table), ("SandboxText", SandboxText.Table),
                    ("CommanderText", CommanderText.Table), ("NameText", NameText.Table), ("StoryText", StoryText.Table), ("DialogueText", DialogueText.Table), ("EventText", EventText.Table),
                };
                foreach (var (name, table) in tables)
                    foreach (var kv in table)
                        yield return (kv.Key, kv.Value.en, kv.Value.vi, name);
            }
        }

        /// <summary>Every key of every text table (the checks and <see cref="Relabel"/> read them).</summary>
        public static IEnumerable<string> Keys
        {
            get
            {
                foreach (var e in Entries) yield return e.key;
            }
        }

        /// <summary>The table has this key (optional texts, such as a vehicle's role note).</summary>
        public static bool Has(string key) => Table.ContainsKey(key) || GuideText.Table.ContainsKey(key) || CampaignText.Table.ContainsKey(key) || UnitText.Table.ContainsKey(key) ||
            BigAttackText.Table.ContainsKey(key) || OrbitalText.Table.ContainsKey(key) || BossText.Table.ContainsKey(key) || SandboxText.Table.ContainsKey(key) ||
            CommanderText.Table.ContainsKey(key) || NameText.Table.ContainsKey(key) ||
            StoryText.Table.ContainsKey(key) || DialogueText.Table.ContainsKey(key) || EventText.Table.ContainsKey(key);

        /// <summary>[[word]] marks a key word in a text: drawn bold in the accent colour (UI rich text).</summary>
        public static string Highlight(string text) =>
            System.Text.RegularExpressions.Regex.Replace(text, @"\[\[(.+?)\]\]", "<b><color=#F2A33A>$1</color></b>");

        /// <summary>Vehicle or support card name.</summary>
        public static string Card(string defId) => Has("unit." + defId) || IsBranch(defId) ? Unit(defId) : Support(defId);

        /// <summary>A tower branch's id ("aa_turret.flak"): the tower's name with the branch's (never the raw "support." key).</summary>
        private static bool IsBranch(string defId)
        {
            var dot = defId?.IndexOf('.') ?? -1;
            return dot > 0 && Table.ContainsKey("unit." + defId.Substring(0, dot));
        }

        /// <summary>
        /// A card's short name (prompt 11 B: at most about 14 letters, for one line on a card, the deck strip,
        /// chips and narrow lists), falling back to its full name; a tower branch without one of its own reads
        /// as the branch's name alone.
        /// </summary>
        public static string Short(string defId)
        {
            if (defId == null) return "";
            if (Has("short." + defId)) return Get("short." + defId);
            return IsBranch(defId) ? Branch(defId) : Card(defId);
        }
    }
}
